// ── statusOf: one semantic role per state, across the whole ladder (D15) ─────

// cch-w34-s6: every host-set fixture below now carries last_seen_at, because a
// live box that has REPORTED is what these cases describe. The control plane's
// serializer always sends the field (router.ex barkpark_json), and a null value
// is now its own state ("Never reported") rather than a silent "Degraded".
const SEEN = "2026-08-06T09:00:00Z";

test("statusOf collapses every fleet state into one {role,label} (D15 ordering)", () => {
  const cases = [
    [{ deprovision_status: "failed" }, "danger", "Removal failed"],
    [{ provision_status: "failed" }, "danger", "Failed"],                        // no host
    [{ host: "h", suspended: true }, "danger", "Suspended"],
    [{ host: "h", last_seen_at: SEEN, health_status: "down", agent_status: "online" }, "warn", "Degraded"],
    [{ host: "h", last_seen_at: SEEN, health_status: "up", agent_status: "offline" }, "warn", "Degraded"],
    [{ host: "h", last_seen_at: null, health_status: "up", agent_status: "offline" }, "neutral", "Never reported"],
    [{ host: "h", last_seen_at: SEEN, health_status: "up", agent_status: "online", update_state: "behind" }, "info", "Update available"],
    [{ deprovision_status: "pending" }, "info", "Removing"],
    [{ deprovision_status: "claimed" }, "info", "Removing"],
    [{}, "info", "Provisioning"],                                                // no host, nothing failed
    [{ host: "h", last_seen_at: SEEN, health_status: "up", agent_status: "online" }, "ok", "Healthy"],
  ];
  for (const [bp, role, label] of cases) {
    const s = hooks.statusOf(bp);
    assert.equal(s.role, role, JSON.stringify(bp) + " role");
    assert.equal(s.label, label, JSON.stringify(bp) + " label");
    assert.equal(typeof s.detail, "string");
  }
  assert.equal(hooks.statusOf(null).role, "info"); // null → provisioning-ish, never throws
});

test("statusOf: 'not removing' qualifier — a suspended box mid-teardown reads as Removing (D15 §3)", () => {
  assert.equal(hooks.statusOf({ suspended: true, deprovision_status: "pending" }).label, "Removing");
});

// Cross-surface parity guard (matches cloud_status_cmd.go statusOf): a host-set
// box classifies on its HEALTH, never on a stale/failed latest provision job.
// A failed provision must not force a live-but-unhealthy box to a false-green
// "ok" — it must read Degraded, exactly as the CLI does.
test("classifyBp: a host-set box ignores a failed provision job, ranks on health (Go parity)", () => {
  // host up + healthy, failed latest provision → still ok (the box is serving)
  assert.equal(hooks.classifyBp({ host: "h", last_seen_at: SEEN, provision_status: "failed", health_status: "up", agent_status: "online" }), "ok");
  // host up + UNHEALTHY, failed latest provision → degraded, NOT a false-green ok
  assert.equal(hooks.classifyBp({ host: "h", last_seen_at: SEEN, provision_status: "failed", health_status: "down", agent_status: "online" }), "degraded");
  // no host + failed provision is still the terminal "failed" (rank 2)
  assert.equal(hooks.classifyBp({ provision_status: "failed" }), "failed");
});

// ── attentionRank ordering + tiebreak vs a mixed fixture (D15) ──────────────

const MIXED = [
  { name: "healthy-b", host: "h", last_seen_at: SEEN, health_status: "up", agent_status: "online" },       // ok (9)
  { name: "removing-x", deprovision_status: "claimed" },                               // removing (7)
  { name: "gone-fail", deprovision_status: "failed" },                                 // removal_failed (1)
  { name: "Alpha-degraded", host: "h", last_seen_at: SEEN, health_status: "down", agent_status: "online" },// degraded (4)
  { name: "prov", },                                                                    // provisioning (8)
  { name: "susp", host: "h", suspended: true },                                        // suspended (3)
  { name: "behind-1", host: "h", last_seen_at: SEEN, health_status: "up", agent_status: "online", update_state: "behind" }, // behind (6)
  { name: "prov-fail", provision_status: "failed" },                                   // failed (2)
  { name: "never-said", host: "h", last_seen_at: null, health_status: "up", agent_status: "offline" }, // unreported (5)
  { name: "healthy-a", host: "h", last_seen_at: SEEN, health_status: "up", agent_status: "online" },       // ok (9), tiebreak before healthy-b
];

test("attentionRank matches the decision-32 fixture rank for each state", () => {
  // jpf-w1-queue-age-alarm: these are the FIXTURE ranks (attention_order.json),
  // no longer a private 1–9 numbering — 5 and 6 are strained/filling, which
  // this console does not classify yet (the named gap in ATTENTION_RANK).
  const rankByName = Object.fromEntries(MIXED.map((b) => [b.name, hooks.attentionRank(b)]));
  assert.equal(rankByName["gone-fail"], 1);
  assert.equal(rankByName["prov-fail"], 2);
  assert.equal(rankByName["susp"], 3);
  assert.equal(rankByName["Alpha-degraded"], 4);
  assert.equal(rankByName["never-said"], 7);
  assert.equal(rankByName["behind-1"], 9);
  assert.equal(rankByName["removing-x"], 10);
  assert.equal(rankByName["prov"], 11);
  assert.equal(rankByName["healthy-a"], 12);
});

// cch-w34-s6 (charter D332(b)), stated as an ORDERING, not just as numbers:
// measured failure > unknown > pending > ok. If a future edit slides
// `unreported` below the pending states, this reds regardless of renumbering.
test("cch-w34-s6: the unknown state ranks below every measured failure and above every pending state", () => {
  const rank = (bp) => hooks.attentionRank(bp);
  const unreported = { host: "h", last_seen_at: null };
  for (const failure of [
    { deprovision_status: "failed" },
    { provision_status: "failed" },
    { host: "h", suspended: true },
    { host: "h", last_seen_at: SEEN, health_status: "down", agent_status: "online" },
  ]) assert.ok(rank(failure) < rank(unreported), "a measured failure outranks unknown: " + JSON.stringify(failure));
  for (const pending of [
    { host: "h", last_seen_at: SEEN, health_status: "up", agent_status: "online", update_state: "behind" },
    { deprovision_status: "pending" },
    {},
    { host: "h", last_seen_at: SEEN, health_status: "up", agent_status: "online" },
  ]) assert.ok(rank(unreported) < rank(pending), "unknown outranks pending/ok: " + JSON.stringify(pending));
});

test("attentionCompare sorts most-urgent-first, tiebreak name ascending case-insensitive", () => {
  const sorted = MIXED.slice().sort(hooks.attentionCompare).map((b) => b.name);
  assert.deepEqual(sorted, [
    "gone-fail",      // 1
    "prov-fail",      // 2
    "susp",           // 3
    "Alpha-degraded", // 4
    "never-said",     // 5
    "behind-1",       // 6
    "removing-x",     // 7
    "prov",           // 8
    "healthy-a",      // 9, tiebreak: "healthy-a" < "healthy-b"
    "healthy-b",      // 9
  ]);
});

// ── bucketOf / fleetSummary / filterFleet ───────────────────────────────────

test("bucketOf maps ranks 1–9 → attention, 10–11 → in-flight, 12 → healthy", () => {
  assert.equal(hooks.bucketOf({ deprovision_status: "failed" }), "attention"); // 1
  assert.equal(hooks.bucketOf({ host: "h", last_seen_at: SEEN, health_status: "down" }), "attention"); // 4
  assert.equal(hooks.bucketOf({ host: "h", last_seen_at: null }), "attention"); // 7 unreported
  assert.equal(hooks.bucketOf({ host: "h", last_seen_at: SEEN, health_status: "up", agent_status: "online", queued_deploy_age_seconds: 420 }), "attention"); // 8 deploy_stalled
  assert.equal(hooks.bucketOf({ deprovision_status: "pending" }), "in-flight"); // 10
  assert.equal(hooks.bucketOf({}), "in-flight"); // 11 provisioning
  assert.equal(hooks.bucketOf({ host: "h", last_seen_at: SEEN, health_status: "up", agent_status: "online" }), "healthy"); // 12
});

test("fleetSummary counts buckets — mixed, empty, and all-healthy", () => {
  const s = hooks.fleetSummary(MIXED);
  assert.equal(s.total, 10);
  assert.equal(s.attention, 6); // removal_failed, failed, suspended, degraded, unreported, behind (attention ranks)
  assert.equal(s["in-flight"], 2); // removing, provisioning (ranks 10–11) — the fixture's hyphenated bucket key
  assert.equal(s.healthy, 2);   // healthy-a, healthy-b (rank 12)
  assert.equal(s.attention + s["in-flight"] + s.healthy, s.total);

  // Spread sandbox-realm returns into the test realm before deepEqual (the
  // node:vm objects carry a different Object.prototype — same trick as parseHash).
  assert.deepEqual({ ...hooks.fleetSummary([]) }, { attention: 0, "in-flight": 0, healthy: 0, total: 0 });
  assert.deepEqual({ ...hooks.fleetSummary(null) }, { attention: 0, "in-flight": 0, healthy: 0, total: 0 });

  const allHealthy = [
    { name: "a", host: "h", last_seen_at: SEEN, health_status: "up", agent_status: "online" },
    { name: "b", host: "h", last_seen_at: SEEN, health_status: "up", agent_status: "online" },
  ];
  assert.deepEqual({ ...hooks.fleetSummary(allHealthy) }, { attention: 0, "in-flight": 0, healthy: 2, total: 2 });
});

test("filterFleet returns exactly one bucket; null bucket → the whole list (copied)", () => {
  const attention = hooks.filterFleet(MIXED, "attention").map((b) => b.name).sort();
  assert.deepEqual(attention, ["Alpha-degraded", "behind-1", "gone-fail", "never-said", "prov-fail", "susp"].sort());
  assert.equal(hooks.filterFleet(MIXED, "in-flight").length, 2);
  assert.equal(hooks.filterFleet(MIXED, "healthy").length, 2);
  const all = hooks.filterFleet(MIXED, null);
  assert.equal(all.length, MIXED.length);
  assert.notEqual(all, MIXED); // a copy, not the same reference
  assert.deepEqual([...hooks.filterFleet(null, "attention")], []);
});

// ── the decision-32 fixture is now the SPA's asserter too (jpf-w1) ──────────
//
// Until this test, Go was attention_order.json's ONLY asserter and this file
// drifted silently: the SPA ran a private 1–9 rank ladder and emitted the
// bucket string "inflight" where the fixture (and Go, and -o json) say
// "in-flight". This is the verify_probes.json pattern (C8 below): read the
// committed fixture, hold the SPA's vocabulary to it byte-for-byte.

test("D32: the SPA attention vocabulary matches attention_order.json", () => {
  const fixture = JSON.parse(
    fs.readFileSync(new URL("./__fixtures__/attention_order.json", import.meta.url), "utf8"),
  );
  const states = fixture.states;

  // FAIL CLOSED ON AN EMPTY CORPUS: a fixture that parses to zero states must
  // red here, never green a loop that asserted nothing. The floor states the
  // sample size the rest of the test runs over.
  assert.ok(Array.isArray(states) && states.length >= 12,
    "attention_order.json carries " + (Array.isArray(states) ? states.length : 0) +
    " states — the decision-32 vocabulary is at least twelve; an empty fixture would green every loop below vacuously");

  // The BUCKET STRINGS, from the fixture side — including the hyphenated
  // "in-flight" this file used to misspell as "inflight". Compared against a
  // literal, not against the SPA, so both-empty can never scan green.
  assert.deepEqual([...new Set(states.map((st) => st.bucket))],
    ["attention", "in-flight", "healthy"]);

  // …and from the SPA side: the three strings bucketOfRank can produce are the
  // fixture's three, verbatim.
  assert.equal(hooks.bucketOfRank(1), "attention");
  assert.equal(hooks.bucketOfRank(10), "in-flight");
  assert.equal(hooks.bucketOfRank(12), "healthy");

  // KNOWN GAP, pinned to exactly two names: fixture states the SPA does not
  // classify yet (their inputs — load/disk vitals — have no classifyBp arm).
  // A THIRD state missing from ATTENTION_RANK reds this test; so does closing
  // the gap without deleting its entry here.
  const SPA_GAP = ["strained", "filling"];
  const ranks = { ...hooks.ATTENTION_RANK };
  assert.deepEqual(states.map((st) => st.state).filter((k) => !(k in ranks)), SPA_GAP,
    "fixture states missing from the SPA ladder must be exactly the named gap");

  // Every state the SPA ranks: fixture-listed, on the FIXTURE's rank, in the
  // FIXTURE's bucket. This is the assertion that reds if either side renumbers
  // alone — the drift this slice found (1–9 vs 1–11) could never have shipped
  // through it.
  for (const st of states) {
    if (SPA_GAP.includes(st.state)) continue;
    assert.equal(ranks[st.state], st.rank,
      st.state + ": SPA rank " + ranks[st.state] + " != fixture rank " + st.rank);
    assert.equal(hooks.bucketOfRank(st.rank), st.bucket,
      st.state + ": SPA bucket for rank " + st.rank + " != fixture bucket " + st.bucket);
  }

  // No SPA state outside the fixture: a rung minted here alone is the same
  // drift in the other direction.
  for (const k of Object.keys(ranks)) {
    assert.ok(states.some((st) => st.state === k),
      "SPA state " + k + " is not in attention_order.json");
  }

  // The row this slice adds, by name: present in the fixture AND in the SPA,
  // warn-toned, attention-bucketed, between unreported and behind.
  const stalled = states.find((st) => st.state === "deploy_stalled");
  assert.ok(stalled, "deploy_stalled missing from the fixture");
  assert.equal(stalled.tone, "warn");
  assert.equal(stalled.bucket, "attention");
  assert.ok(ranks.unreported < ranks.deploy_stalled && ranks.deploy_stalled < ranks.behind,
    "deploy_stalled must sit after unreported and before behind");
});

// ── the PREDICATE gets a cross-surface asserter too (dr-w25) ────────────────
//
// The D32 test above holds the SPA's RANK TABLE to attention_order.json. It says
// nothing about classifyBp — a rung could keep its fixture rank forever and
// still be unreachable, or reachable only through half its inputs. That is
// exactly the defect this slice repairs: `behind` was reachable through
// update_state and NOT through commit_ancestry, so a box the control plane had
// measured 2,493 commits behind main classified `ok` and rendered live-green.
//
// The expected side is DERIVED from the fixture (states minus the named gap),
// never a second hand-typed ladder: a state added to attention_order.json with
// no witness here reds this test rather than scanning green.
test("dr-w25: every fixture state the SPA ranks is REACHABLE, and `behind` is reachable by commit ancestry", () => {
  const fixture = JSON.parse(
    fs.readFileSync(new URL("./__fixtures__/attention_order.json", import.meta.url), "utf8"),
  );
  const SPA_GAP = ["strained", "filling"]; // same named gap the D32 test pins
  const expected = fixture.states.map((st) => st.state).filter((k) => !SPA_GAP.includes(k));
  assert.ok(expected.length >= 10,
    "derived from a fixture carrying only " + expected.length + " classifiable states — an empty corpus would green every loop below");

  const LIVE = { host: "h", last_seen_at: SEEN, health_status: "up", agent_status: "online" };
  // One witness payload per fixture state, keyed BY THE FIXTURE'S NAMES.
  const WITNESS = {
    removal_failed: { deprovision_status: "failed" },
    failed: { provision_status: "failed" },
    suspended: { host: "h", suspended: true },
    degraded: { host: "h", last_seen_at: SEEN, health_status: "down", agent_status: "online" },
    unreported: { host: "h", last_seen_at: null },
    deploy_stalled: { ...LIVE, queued_deploy_age_seconds: 420 },
    behind: { ...LIVE, update_state: "behind" },
    removing: { deprovision_status: "pending" },
    provisioning: {},
    ok: { ...LIVE },
  };
  assert.deepEqual(Object.keys(WITNESS).slice().sort(), expected.slice().sort(),
    "a fixture state gained or lost a witness — the predicate and attention_order.json have drifted");

  for (const state of expected) {
    assert.equal(hooks.classifyBp(WITNESS[state]), state, state + " must be reachable from classifyBp");
    const rank = fixture.states.find((st) => st.state === state).rank;
    assert.equal(hooks.attentionRank(WITNESS[state]), rank,
      state + ": classifyBp's witness ranks " + hooks.attentionRank(WITNESS[state]) + ", fixture says " + rank);
  }

  // THE ROW THIS SLICE REPAIRS — the production payload, verbatim: the control
  // plane measured 2,493 commits behind main while the release-tag grade read
  // `current` (no tag has been cut since 2026-07-08). Before this slice the
  // SECOND source was invisible to the predicate and this box classified "ok".
  const tagCurrentCommitBehind = { ...LIVE, update_state: "current", commit_ancestry: "behind", commit_distance: 2493 };
  assert.equal(hooks.classifyBp(tagCurrentCommitBehind), "behind",
    "a box the plane measured behind main must not classify live-green because its release tag grades itself current");
  assert.equal(hooks.attentionRank(tagCurrentCommitBehind),
    fixture.states.find((st) => st.state === "behind").rank);
  assert.equal(hooks.bucketOf(tagCurrentCommitBehind), "attention");

  // …and the RENDERED heading an operator reads (criterion 1's paste).
  const s = hooks.statusOf(tagCurrentCommitBehind);
  assert.equal(s.label, "Update available");
  assert.equal(s.role, "info");
  // Not the false all-clear "A newer release is available": the detail names the
  // disagreement, in the Go twin's phrasing (behindDetail).
  assert.equal(s.detail, "2493 commits behind main · release-tag grade still reads current");

  // The unmetered arm: ancestry behind, distance null — still `behind`, and the
  // detail never fabricates a number.
  const unmetered = { ...LIVE, update_state: "current", commit_ancestry: "behind", commit_distance: null };
  assert.equal(hooks.classifyBp(unmetered), "behind");
  assert.equal(hooks.statusOf(unmetered).detail,
    "behind main by an unmeasured number of commits · release-tag grade still reads current");

  // NON-REGRESSION, both directions: ancestry `current` is not behind, an absent
  // ancestry (older control plane) is not behind, and a release-tag behind keeps
  // its pre-existing release sentence rather than inheriting the commit one.
  assert.equal(hooks.classifyBp({ ...LIVE, commit_ancestry: "current", commit_distance: 0 }), "ok");
  assert.equal(hooks.classifyBp({ ...LIVE, commit_distance: 2493 }), "ok");
  assert.equal(hooks.statusOf({ ...LIVE, update_state: "behind", update_latest_release: "1.2.3" }).detail, "→ v1.2.3");
  // A box that is BOTH is still one rung, and the tag sentence wins (the UPDATE
  // column already shows running → latest) — Go's precedence, verbatim.
  assert.equal(hooks.statusOf({ ...LIVE, update_state: "behind", commit_ancestry: "behind", commit_distance: 7, update_latest_release: "1.2.3" }).detail, "→ v1.2.3");
  // A non-live box is never re-ranked by commit ancestry — suspended outranks it.
  assert.equal(hooks.classifyBp({ host: "h", suspended: true, commit_ancestry: "behind" }), "suspended");
  assert.equal(hooks.classifyBp({ ...LIVE, last_seen_at: null, commit_ancestry: "behind" }), "unreported");
});

// ── deploy_stalled (jpf-w1 D6/D7): the queued-age alarm, client side ────────

test("jpf-w1: a 5-minute unclaimed queued deploy is deploy_stalled — warn, attention, age named", () => {
  const live = { host: "h", last_seen_at: SEEN, health_status: "up", agent_status: "online" };
  const stalled = { ...live, queued_deploy_age_seconds: 420 };
  assert.equal(hooks.classifyBp(stalled), "deploy_stalled");
  assert.equal(hooks.bucketOf(stalled), "attention");
  const s = hooks.statusOf(stalled);
  assert.equal(s.role, "warn"); // NOT the info/blue tone "queued" would get
  assert.equal(s.label, "Deploy stalled");
  assert.match(s.detail, /queued 7m/i);       // the criterion: the age, named
  assert.match(s.detail, /no builder/i);      // and the fact that makes it a problem
});

test("jpf-w1: the fence never fires on a fresh queue, a nil field, or a non-number", () => {
  const live = { host: "h", last_seen_at: SEEN, health_status: "up", agent_status: "online" };
  // Fresh queue (under 300s) → ok: a just-enqueued deploy is news, not an alarm.
  assert.equal(hooks.classifyBp({ ...live, queued_deploy_age_seconds: 299 }), "ok");
  // nil / absent — an older CP or nothing queued — must NEVER read as stalled.
  assert.equal(hooks.classifyBp({ ...live, queued_deploy_age_seconds: null }), "ok");
  assert.equal(hooks.classifyBp(live), "ok");
  // A stringly-typed age is a wire bug, not a stall.
  assert.equal(hooks.classifyBp({ ...live, queued_deploy_age_seconds: "420" }), "ok");
  // Exactly the fence (>= 300, not > 300).
  assert.equal(hooks.classifyBp({ ...live, queued_deploy_age_seconds: 300 }), "deploy_stalled");
});

test("jpf-w1: a sick box's stuck queue is a symptom — degraded/unreported outrank deploy_stalled", () => {
  const stalledAge = { queued_deploy_age_seconds: 9000 };
  assert.equal(hooks.classifyBp({ host: "h", last_seen_at: SEEN, health_status: "up", agent_status: "offline", ...stalledAge }), "degraded");
  assert.equal(hooks.classifyBp({ host: "h", last_seen_at: null, ...stalledAge }), "unreported");
  // …and a stalled box that is ALSO behind reads stalled: someone asked for
  // this deploy and nobody is building it, which beats passive update drift.
  assert.equal(hooks.classifyBp({ host: "h", last_seen_at: SEEN, health_status: "up", agent_status: "online", update_state: "behind", ...stalledAge }), "deploy_stalled");
});

// ── esc: the HTML-injection shield used by every renderer ───────────────────

test("esc escapes all five HTML metacharacters", () => {
  assert.equal(hooks.esc("<&\"'>"), "&lt;&amp;&quot;&#39;&gt;");
  assert.equal(hooks.esc(null), "");
});

// ── cch-w34-s6: the console says "never reported" ────────────────────────────
//
// Production (2026-08-06) carried 3 of 8 barkparks with last_seen_at NULL — the
// oldest inserted 38 days earlier. The pill read "Degraded · Agent offline" (the
// grammar of a box that WAS online and left) and the rail read "Health: Up"
// beside "Last seen: —". cch-w34-s2 fixed the two WRITERS that produced the
// green health value; it shipped no backfill, so legacy rows still carry it.
// This slice gives the state its own word, and renders the evidence the
// serializer has been sending and the console read zero times.
//
// The production row shape, verbatim in the fields that decide the state.
const NEVER_REPORTED = {
  id: "bp-never", name: "Gyldendal", host: "5.75.169.183", url: "https://x.barkpark.cloud",
  health_status: "up", agent_status: "offline", last_seen_at: null,
  inserted_at: new Date(Date.now() - 38 * 24 * 3600 * 1000).toISOString(),
  unreachable_count: 3, unreachable_notification_sent: true,
  provider: "hetzner", region: "fsn1", server_type: "cx22", provision_status: "succeeded",
};

test("cch-w34-s6: a box we have never heard from is its own state, not 'Degraded'", () => {
  assert.equal(hooks.classifyBp(NEVER_REPORTED), "unreported");
  const s = hooks.statusOf(NEVER_REPORTED);
  assert.equal(s.label, "Never reported");
  assert.equal(s.role, "neutral");
  assert.doesNotMatch(s.label + " " + s.detail, /Degraded|Agent offline/);
  // and the fleet row's pill carries it (statusPill's only inputs are statusOf)
  const row = hooks.fleetRow(NEVER_REPORTED);
  assert.match(row, /status-pill--neutral/);
  assert.match(row, /status-pill-label">Never reported</);
  assert.doesNotMatch(row, /Degraded/);
});

test("cch-w34-s6: the instance rail stops printing 'Health: Up' and a bare '—' for it", () => {
  const html = hooks.instanceOverviewHtml(NEVER_REPORTED, {});
  // the Activity row is lastSeenText, not fmtWhen's em dash
  assert.match(html, /Last seen<\/span><span class="v plain">Never reported/);
  // the Runtime row no longer reprints the cached green word
  assert.doesNotMatch(html, /Health<\/span><span class="v">Up</);
  assert.match(html, /Health<\/span><span class="v">Never reported</);
  // a box that HAS reported keeps a real relative freshness line
  const seen = { ...NEVER_REPORTED, last_seen_at: new Date(Date.now() - 120000).toISOString(), agent_status: "online" };
  assert.match(hooks.instanceOverviewHtml(seen, {}), /Last seen<\/span><span class="v plain">Reported 2m ago</);
  assert.match(hooks.instanceOverviewHtml(seen, {}), /Health<\/span><span class="v">Up</);
});

test("cch-w34-s6: lastSeenText names the state and its age; missedChecksText renders unreachable_count", () => {
  // the renderer this slice adds, by name
  assert.equal(typeof hooks.lastSeenText, "function");
  assert.equal(typeof hooks.missedChecksText, "function");
  assert.equal(typeof hooks.neverReportedEvidence, "function");
  const line = hooks.lastSeenText(NEVER_REPORTED);
  assert.match(line, /^Never reported · Created 38d ago · 3 missed checks$/);
  // the evidence the serializer has shipped since cch-w34-s2 and the console
  // read ZERO times before this slice.
  assert.equal(hooks.missedChecksText({ unreachable_count: 3 }), "3 missed checks");
  assert.equal(hooks.missedChecksText({ unreachable_count: 1 }), "1 missed check");
  // absent / zero / non-numeric → silence, never "0 missed checks"
  assert.equal(hooks.missedChecksText({}), "");
  assert.equal(hooks.missedChecksText({ unreachable_count: 0 }), "");
  assert.equal(hooks.missedChecksText({ unreachable_count: null }), "");
  assert.equal(hooks.missedChecksText(null), "");
  // a row with nothing to show still names the state, never a bare dangling "·"
  assert.equal(hooks.lastSeenText({ host: "h" }), "Never reported");
  assert.equal(hooks.lastSeenText({ host: "h", last_seen_at: "not-a-date" }), "Never reported");
});

test("cch-w34-s6: a box that HAS reported still surfaces its missed-check count", () => {
  // unreachable_count is evidence on the degraded axis too — the sweep counted
  // these, and before this slice no surface in the console said so.
  const lost = { host: "h", last_seen_at: SEEN, health_status: "down", agent_status: "offline", unreachable_count: 7 };
  const s = hooks.statusOf(lost);
  assert.equal(s.label, "Degraded");
  assert.match(s.detail, /Health down · Agent offline · 7 missed checks/);
  // and stays silent when the counter is zero
  assert.equal(hooks.statusOf({ ...lost, unreachable_count: 0 }).detail, "Health down · Agent offline");
});

test("cch-w34-s6: the unknown state names EVIDENCE ONLY — no remediation, no next step (D332(d))", () => {
  const s = hooks.statusOf(NEVER_REPORTED);
  const copy = s.label + " " + s.detail + " " + hooks.lastSeenText(NEVER_REPORTED);
  // no imperative, no advice, no support escalation — the charter's line.
  assert.doesNotMatch(copy, /retry|try again|check the|contact|restart|reinstall|run |ssh|should|make sure|verify/i);
});

test("cch-w34-s6: statusOf is total over the CLOSED state enum — nothing falls through to a calm label", () => {
  // charter D33: a MAP[state] || "…" tail announces the CALMEST word over the
  // most severe state. The enum is pinned, and every member has an explicit arm.
  const KINDS = ["removal_failed", "failed", "suspended", "degraded", "unreported",
    "deploy_stalled", "behind", "removing", "provisioning", "ok"];
  assert.deepEqual([...hooks.attentionKinds].sort(), KINDS.slice().sort(),
    "a new fleet state was added without a statusOf arm (or one was removed)");
  const REP = {
    removal_failed: { deprovision_status: "failed" },
    failed: { provision_status: "failed" },
    suspended: { host: "h", suspended: true },
    degraded: { host: "h", last_seen_at: SEEN, health_status: "down", agent_status: "online" },
    unreported: { host: "h", last_seen_at: null },
    deploy_stalled: { host: "h", last_seen_at: SEEN, health_status: "up", agent_status: "online", queued_deploy_age_seconds: 420 },
    behind: { host: "h", last_seen_at: SEEN, health_status: "up", agent_status: "online", update_state: "behind" },
    removing: { deprovision_status: "pending" },
    provisioning: {},
    ok: { host: "h", last_seen_at: SEEN, health_status: "up", agent_status: "online" },
  };
  for (const kind of KINDS) {
    assert.equal(hooks.classifyBp(REP[kind]), kind, kind + " must be reachable");
    const s = hooks.statusOf(REP[kind]);
    // THE MUTATION THIS CATCHES: delete an arm from statusOf and its kind lands
    // on the fallthrough, which is loud ("Unclassified", warn) — never calm.
    assert.notEqual(s.label, "Unclassified", kind + " has no explicit statusOf arm");
    assert.ok(["ok", "info", "warn", "danger", "neutral"].includes(s.role), kind + " role");
  }
});

test("cch-w34-s6: the console's 'Unknown' neutral role is now REACHED, and the tail is not calm", () => {
  // Before this slice statusOf ended on an unreachable `{role:"neutral",
  // label:"Unknown"}` — a state the console declared and could never produce.
  // The neutral role is now produced by the only genuinely unknown thing.
  assert.equal(hooks.statusOf(NEVER_REPORTED).role, "neutral");
  const roles = new Set([...hooks.attentionKinds].map((k) => k));
  assert.ok(roles.has("unreported"));
});

// ── cch-w34-s6 (2): the provision console stops promising output to a job that
// ── already ended. Production provision_jobs: 3 succeeded + 1 failed with a
// ── completely empty console. "yet" is a promise nothing will keep.

test("cch-w34-s6: consoleTail splits the empty caption on the job's terminal state", () => {
  assert.match(hooks.consoleTail([]), /No console output yet\./);            // pending, unchanged
  assert.match(hooks.consoleTail([], { terminal: false }), /No console output yet\./);
  const done = hooks.consoleTail([], { terminal: true });
  assert.match(done, /No console output was recorded\./);
  assert.doesNotMatch(done, /yet/);
  // lines always win over either caption
  assert.match(hooks.consoleTail([{ line: "activate: build complete", at: null }], { terminal: true }),
    /activate: build complete/);
});

test("cch-w34-s6: a FAILED provision with an empty console no longer says 'yet'", () => {
  const failed = { id: "b", provision_status: "failed", host: null, provision_console: [] };
  const html = hooks.instanceTimelineHtml(failed, Date.now(), {});
  assert.match(html, /No console output was recorded\./);
  assert.doesNotMatch(html, /No console output yet\./);
  // a SUCCEEDED job (host set) is terminal too
  const succeeded = { id: "b", provision_status: "succeeded", host: "h", provision_console: [] };
  assert.match(hooks.instanceTimelineHtml(succeeded, Date.now(), {}), /No console output was recorded\./);
  // a job still running keeps the pending caption — it really may fill in
  const running = { id: "b", provision_status: "claimed", host: null, provision_console: [] };
  assert.match(hooks.instanceTimelineHtml(running, Date.now(), {}), /No console output yet\./);
});

// ── cch-w34-s6 (3): pin wave 33's mid-stage narration arm against the shape
// ── production actually produces (charter D384: 96.3% of console entries carry
// ── a status; the arm is already paid for 3,019 rows and was unpinned here).

test("cch-w34-s6: a failed deploy whose last entry is {stage:'HEALTH',status:'running'} discloses the cut", () => {
  const d = {
    id: "dep-health", status: "failed",
    console: [
      { line: "PLAN: resolved", at: null, stage: "PLAN", status: "done" },
      { line: "BUILD: image pushed", at: null, stage: "BUILD", status: "done" },
      { line: "HEALTH running", at: null, stage: "HEALTH", status: "running" },
    ],
  };
  const html = hooks.deployConsoleHtml(d, hooks.deployIsActive("failed"));
  assert.match(html, /narration ended mid-HEALTH/);
  // and the count still reads the REAL number of entries, never inflated
  assert.match(html, /deploy-console-count">3 lines/);
});

test("cch-w34-s6: the n=1 statusless-terminal shape records what it renders TODAY", () => {
  // One production row ends on a plain {line, at} with NO status key. Absent
  // status is SILENCE, so no cut is claimed — asserted so a future change to
  // that arm is VISIBLE rather than silent.
  const d = {
    id: "dep-statusless", status: "failed",
    console: [
      { line: "PLAN: resolved", at: null, stage: "PLAN", status: "done" },
      { line: "activate: build complete — handing off to release", at: null },
    ],
  };
  const html = hooks.deployConsoleHtml(d, hooks.deployIsActive("failed"));
  assert.doesNotMatch(html, /narration ended/);
  assert.match(html, /deploy-console-count">2 lines/);
  assert.match(html, /activate: build complete/);
});

// ── dwb-18: queued (unclaimed) deploy gets an honest pre-claim state ─────────
// A deploy that's enqueued but no builder has claimed it (status "queued", no
// console lines) must NOT render the dark "Waiting for the first log line…"
// build console — that implies an active stream. It gets a calm muted caption
// and no console panel until the first real log line flips it to building.

test("dwb-18: the deploy pre-claim helpers are exported", () => {
  assert.equal(typeof hooks.deployIsPreClaim, "function");
  assert.equal(typeof hooks.deployDetailHtml, "function");
  assert.equal(typeof hooks.deployConsoleHtml, "function");
});

test("dwb-18: a queued row with no console yields the queued caption, not a build console", () => {
  const d = { id: "dep1", status: "queued" };
  const detail = hooks.deployDetailHtml(d, "queued");
  assert.match(detail, /Queued — waiting for a builder to pick this up/);
  assert.match(detail, /deploy-queued/);
  // No dark console panel at all while pre-claim.
  const console = hooks.deployConsoleHtml(d, hooks.deployIsActive("queued"));
  assert.equal(console, "");
  assert.doesNotMatch(console, /Waiting for the first log line/);
});

test("dwb-18: an optional since-hint appears only when inserted_at is present", () => {
  assert.doesNotMatch(hooks.deployDetailHtml({ id: "d", status: "queued" }, "queued"), /since/);
  assert.match(
    hooks.deployDetailHtml({ id: "d", status: "queued", inserted_at: "2026-07-03T10:00:00Z" }, "queued"),
    /\(since /,
  );
});

test("dwb-18: a building row still opens the dark build console", () => {
  const d = { id: "dep2", status: "building" };
  const console = hooks.deployConsoleHtml(d, hooks.deployIsActive("building"));
  assert.match(console, /deploy-console/);
  assert.match(console, /Waiting for the first log line/); // placeholder until first line
  // building is NOT pre-claim → no queued caption
  assert.equal(hooks.deployIsPreClaim(d, "building"), false);
});

test("dwb-18: once the first log line arrives, a still-queued row renders the console normally", () => {
  const d = { id: "dep3", status: "queued", console: [{ at: null, line: "cloning repo" }] };
  assert.equal(hooks.deployIsPreClaim(d, "queued"), false);
  const console = hooks.deployConsoleHtml(d, hooks.deployIsActive("queued"));
  assert.match(console, /cloning repo/);
  assert.doesNotMatch(console, /Waiting for the first log line/);
});

// ── cch-w33-s3: the console count stops reading as though it were the whole log
//
// 2,881 failed production deployments across NINE sites end on a console entry
// whose OWN status is still "running" — the narration stopped mid-stage and the
// panel printed a bare "2 lines" as if that were the complete build log. (The
// volume is falling — 821/day on 2026-07-29, 7/day on 2026-08-04 — and the
// failure REASON was never missing: the red fail panel renders above this.) The
// count now discloses what it is not showing, WITHOUT inflating itself.

test("cch-w33-s3: a terminal row whose last entry is still running says the narration was cut", () => {
  const d = {
    id: "dep-cut", status: "failed",
    console: [
      { line: "PLAN: resolved", at: null, stage: "PLAN", status: "done" },
      { line: "BUILD: npm ci", at: null, stage: "BUILD", status: "running" },
    ],
  };
  const html = hooks.deployConsoleHtml(d, hooks.deployIsActive("failed"));
  assert.match(html, /narration ended mid-BUILD/);
  // THE TRAP: the count must still read the real number of entries. A naive
  // implementation renders "3 lines" here, making the very number this test
  // exists to make honest MORE wrong.
  assert.match(html, /deploy-console-count">2 lines/);
});

test("cch-w33-s3: a fully terminal narration gets a bare count, no disclosure", () => {
  const d = {
    id: "dep-whole", status: "failed",
    console: [
      { line: "PLAN: resolved", at: null, stage: "PLAN", status: "done" },
      { line: "BUILD: exited 1", at: null, stage: "BUILD", status: "failed" },
    ],
  };
  const html = hooks.deployConsoleHtml(d, hooks.deployIsActive("failed"));
  assert.doesNotMatch(html, /narration ended/);
  assert.match(html, /deploy-console-count">2 lines</);
});

test("cch-w33-s3: an ACTIVE row is never accused of a cut narration", () => {
  // Mid-flight, a trailing "running" entry is the whole point — the stream is
  // still open. Only a TERMINAL row can have been cut off.
  const d = {
    id: "dep-live", status: "building",
    console: [{ line: "BUILD: npm ci", at: null, stage: "BUILD", status: "running" }],
  };
  const html = hooks.deployConsoleHtml(d, hooks.deployIsActive("building"));
  assert.doesNotMatch(html, /narration ended/);
});

test("cch-w33-s3: a status-less console (the overwhelming majority) claims nothing", () => {
  // Most console entries are a plain {line, at}. Absent status is SILENCE, not
  // evidence of a cut — a guard that fired here would libel every historic row.
  const d = {
    id: "dep-plain", status: "failed",
    console: [{ line: "cloning acme/web", at: null }, { line: "build failed", at: null }],
  };
  const html = hooks.deployConsoleHtml(d, hooks.deployIsActive("failed"));
  assert.doesNotMatch(html, /narration ended/);
  assert.match(html, /deploy-console-count">2 lines</);
});

test("cch-w33-s3: the server's ring drop and line chop surface on the same seam", () => {
  const d = {
    id: "dep-dropped", status: "failed",
    console: [
      { line: "line 6", at: null, dropped_before: 5 },
      { line: "xxxx", at: null, truncated_from: 5000 },
    ],
  };
  const html = hooks.deployConsoleHtml(d, hooks.deployIsActive("failed"));
  assert.match(html, /5 earlier lines dropped/);
  assert.match(html, /1 line truncated/);
  // Still not inflated: two entries, two lines.
  assert.match(html, /deploy-console-count">2 lines/);
});

test("cch-w33-s3: dropped_before === 0 and a marker-less console disclose nothing", () => {
  const d = {
    id: "dep-clean", status: "failed",
    console: [{ line: "a", at: null, dropped_before: 0 }, { line: "b", at: null }],
  };
  const html = hooks.deployConsoleHtml(d, hooks.deployIsActive("failed"));
  assert.doesNotMatch(html, /dropped/);
  assert.doesNotMatch(html, /truncated/);
  assert.match(html, /deploy-console-count">2 lines</);
});

test("cch-w33-s3: the pre-claim and empty-console silences are untouched", () => {
  // Guarded because this slice edits the same function: an absent panel is
  // honest silence, and a console entry on a queued row must not flip
  // deployIsPreClaim's calm caption into a dark empty panel.
  assert.equal(hooks.deployConsoleHtml({ id: "q", status: "queued" }, false), "");
  assert.equal(hooks.deployConsoleHtml({ id: "t", status: "failed", console: [] }, false), "");
  assert.equal(hooks.deployIsPreClaim({ id: "q", status: "queued" }, "queued"), true);
});

// ── cch-w33-bl: two builder paths feed ONE console, and the panel could not
// ── attribute the silence to either of them.
//
// Site.kind routes a deploy down one of two paths that write into the SAME
// `deployment.console` array:
//
//   * kind == "container" — the OFF-BOX builder. internal/builder's consoleTee
//     mirrors every complete line of the real build to
//     POST /v1/builder/deployments/:id/console, which
//     Registry.append_deployment_console/2 stores as a plain {line, at}. NO
//     `stage` key. This console IS the build log.
//   * kind in ["static","node"] — the ON-BOX relay. deploy/site-deploy*.sh
//     posts NOTHING to the console endpoint (`grep -rn console deploy/` finds
//     no endpoint call); the build log stays on the box in
//     $BARKPARK_SITE_LOG_FILE. All this console ever receives is the six
//     synthesized stage lines from Sites.Deploy.record_stage/2 via
//     console_entry/1, whose entries DO carry `stage`.
//
// deployConsoleHtml read only e.line/e.at, so it called both "Build console"
// and printed the entry count as though it were the log's size. For two of the
// three site kinds the affordance claimed to hold a build log it was never
// sent — and an operator staring at six terse stage lines could not tell
// "no build output because none was sent to me" from "no build output because
// the build printed none". The per-entry `stage` key was ALREADY on the wire,
// unread. THE COUNT IS DELIBERATELY UNTOUCHED — it still reads "N lines", the
// real number of entries, exactly as cch-w33-s3 pinned it.

test("cch-w33-bl: a box-driven console (every entry carries a stage) is not called a build console", () => {
  const d = {
    id: "dep-box", status: "failed",
    console: [
      { line: "PLAN done", at: null, stage: "PLAN", status: "done" },
      { line: "BUILD done", at: null, stage: "BUILD", status: "done" },
      { line: "HEALTH failed — probe returned 502", at: null, stage: "HEALTH", status: "failed" },
    ],
  };
  const html = hooks.deployConsoleHtml(d, hooks.deployIsActive("failed"));
  // The affordance names what it actually holds...
  assert.match(html, /Deploy stages/);
  assert.doesNotMatch(html, /Build console/);
  // ...and says where the build output actually is.
  assert.match(html, /built on the box/i);
  assert.match(html, /log stayed there/i);
  // cch-w33-s3's contract survives: the count is the REAL entry count.
  assert.match(html, /deploy-console-count">3 lines/);
});

test("cch-w33-bl: the off-box builder's console is still the build console, and is NOT libelled", () => {
  // THE PATH THAT CURRENTLY WORKS. A fix that only labels the broken path
  // leaves exactly the same ambiguity the next time this one goes quiet.
  const d = {
    id: "dep-container", status: "failed",
    console: [
      { line: "#8 [builder 3/5] RUN npm ci", at: null },
      { line: "npm ERR! code ELIFECYCLE", at: null },
    ],
  };
  const html = hooks.deployConsoleHtml(d, hooks.deployIsActive("failed"));
  assert.match(html, /Build console/);
  assert.doesNotMatch(html, /Deploy stages/);
  assert.doesNotMatch(html, /stayed there/i);
  assert.match(html, /deploy-console-count">2 lines/);
});

test("cch-w33-bl: THE FLIP — the same lines with and without the stage key attribute to different paths", () => {
  // Criterion 3, stated as one test: the discriminator is the ONLY difference
  // between these two fixtures, so a branch that stops reading it fails here.
  const lines = [{ line: "BUILD done", at: null }, { line: "SWITCH done", at: null }];
  const asBuilder = hooks.deployConsoleHtml(
    { id: "f1", status: "failed", console: lines.map((e) => ({ ...e })) },
    false,
  );
  const asBox = hooks.deployConsoleHtml(
    { id: "f2", status: "failed", console: [
      { ...lines[0], stage: "BUILD", status: "done" },
      { ...lines[1], stage: "SWITCH", status: "done" },
    ] },
    false,
  );
  assert.notEqual(
    /Deploy stages/.test(asBox),
    /Deploy stages/.test(asBuilder),
    "adding the stage key must flip the attribution",
  );
  assert.match(asBox, /Deploy stages/);
  assert.match(asBuilder, /Build console/);
});

test("cch-w33-bl: a MIXED console is never accused of holding no build output", () => {
  // A box row that ALSO received real builder lines holds a genuine (partial)
  // build log. Claiming "the log stayed on the box" there would be a new lie in
  // place of the old one, so stage-only is an ALL, never an ANY.
  const d = {
    id: "dep-mixed", status: "failed",
    console: [
      { line: "PLAN done", at: null, stage: "PLAN", status: "done" },
      { line: "npm ERR! code ELIFECYCLE", at: null },
    ],
  };
  const html = hooks.deployConsoleHtml(d, hooks.deployIsActive("failed"));
  assert.match(html, /Build console/);
  assert.doesNotMatch(html, /Deploy stages/);
  assert.doesNotMatch(html, /stayed there/i);
});

test("cch-w33-bl: an empty/pre-claim console is still silence, not a box claim", () => {
  // stage-only is defined over a NON-EMPTY console: `[].every(...)` is true, so
  // a naive predicate would label every empty panel a box deploy.
  assert.equal(hooks.deployConsoleHtml({ id: "q", status: "queued" }, false), "");
  assert.equal(hooks.deployConsoleHtml({ id: "t", status: "failed", console: [] }, false), "");
  const active = hooks.deployConsoleHtml({ id: "b", status: "building" }, true);
  assert.doesNotMatch(active, /Deploy stages/);
  assert.match(active, /Waiting for the first log line/);
});

// ── failureCopy: raw builder failure_reason → human copy for the deploy-fail row

test("failureCopy maps a known builder reason to friendly copy", () => {
  assert.equal(
    hooks.failureCopy("artifact_url is empty (P6 bp deploy must populate it)"),
    "The build source couldn't be fetched.",
  );
  assert.equal(
    hooks.failureCopy("unsupported artifact scheme file://"),
    "The build source couldn't be fetched.",
  );
  assert.equal(
    hooks.failureCopy("this site has no build source configured"),
    "This site has no build source yet. Connect a repo or run bp deploy.",
  );
});

test("failureCopy passes an unrecognized reason through unchanged", () => {
  assert.equal(hooks.failureCopy("some brand new builder error"), "some brand new builder error");
  assert.equal(hooks.failureCopy(""), "");
});

// ── dwb-webhook-deploy-artifact-gap: the born-failed GitHub-push copy + tone ──
// The CP marked a GitHub push deployment born-failed when no source build was
// available. Source builds have since arrived (the router's
// `github_build_available?/1` is repo-present), so this family is now the
// LEGACY tail plus the no-linked-repo defensive fallback — the copy explains
// those rows and promises nothing. FailureCopy.humanize maps the raw
// machine reason to human copy at the JSON boundary, so the client usually
// already receives the human string — the mapping must be IDEMPOTENT.

const GH_HUMAN =
  "This push predates GitHub source builds and can't be built yet — push again to build this commit, or deploy it with bp deploy.";

test("failureCopy: raw github-push reason → the exact server-humanized copy", () => {
  assert.equal(
    hooks.failureCopy(
      "github push builds require the GitHub App integration (not yet available) — deploy an artifact via bp deploy",
    ),
    GH_HUMAN,
  );
});

test("failureCopy: the humanized github-push copy maps to itself (idempotent)", () => {
  // The server humanizes at the JSON boundary, so the client typically receives
  // the already-human string; re-running failureCopy must not double-map it.
  assert.equal(hooks.failureCopy(GH_HUMAN), GH_HUMAN);
});

test("failureCopy/failureTone: byte-drifted server copy (case, U+2019, cannot) still classifies", () => {
  // The Elixir FailureCopy twin owns the wire string; if its copy drifts by a
  // curly apostrophe, casing, or can't→cannot, the client must still recognize
  // the family (re-mapping to canonical copy is the bonus; the tone is the contract).
  const curly = "This push predates GitHub source builds and can’t be built yet — push again to build.";
  assert.equal(hooks.failureCopy(curly), GH_HUMAN);
  assert.equal(hooks.failureTone(curly), "blocked");
  assert.equal(hooks.failureTone("GitHub Push Builds require the GitHub App integration"), "blocked");
  assert.equal(hooks.failureTone("This commit cannot be built yet."), "blocked");
});

test("failureTone: github-push family is 'blocked' (raw + humanized), everything else 'crashed'", () => {
  assert.equal(
    hooks.failureTone("github push builds require the GitHub App integration (not yet available)"),
    "blocked",
  );
  assert.equal(hooks.failureTone(GH_HUMAN), "blocked"); // matches the humanized twin too
  assert.equal(hooks.failureTone("artifact_url is empty (P6 bp deploy must populate it)"), "crashed");
  assert.equal(hooks.failureTone("some brand new builder error"), "crashed");
  assert.equal(hooks.failureTone(null), "crashed"); // total over junk
  assert.equal(hooks.failureTone(""), "crashed");
});

// ── launchEntitled: the client mirror of the server's Billing.entitled?/1 ────
// billing.ex entitled?/1 gates the launch form. The client must agree case-for-
// case so a paying customer (incl. a past_due one in grace) is never shown
// "subscription required" while the server would allow the launch.

const future = new Date(Date.now() + 86400000).toISOString();
const past = new Date(Date.now() - 86400000).toISOString();

test("launchEntitled: helpers are exported", () => {
  assert.equal(typeof hooks.launchEntitled, "function");
  assert.equal(typeof hooks.billingStatusLabel, "function");
  assert.equal(typeof hooks.billingStatusBadge, "function");
  assert.equal(typeof hooks.billingPeriodLine, "function");
});

test("launchEntitled: null / free / expired-trial / no-status are NOT entitled", () => {
  assert.equal(hooks.launchEntitled(null), false);
  assert.equal(hooks.launchEntitled({ status: "active", plan: "free" }), false);
  assert.equal(hooks.launchEntitled({ plan: "trial", current_period_end: past }), false);
  assert.equal(hooks.launchEntitled({ plan: "trial", current_period_end: null }), false);
  assert.equal(hooks.launchEntitled({ plan: "supporter" }), false); // no status
});

test("launchEntitled: active paid + forever + unexpired trial ARE entitled", () => {
  assert.equal(hooks.launchEntitled({ status: "active", plan: "supporter" }), true);
  assert.equal(hooks.launchEntitled({ status: "active", plan: "support_plus" }), true);
  assert.equal(hooks.launchEntitled({ plan: "forever" }), true); // status-independent comp
  assert.equal(hooks.launchEntitled({ plan: "trial", current_period_end: future }), true);
});

test("launchEntitled: past_due mirrors the server grace window (billing.ex:1064)", () => {
  // In grace (period end in the future, or unset) → still entitled.
  assert.equal(hooks.launchEntitled({ status: "past_due", plan: "supporter", current_period_end: future }), true);
  assert.equal(hooks.launchEntitled({ status: "past_due", plan: "supporter", current_period_end: null }), true);
  // Grace elapsed → NOT entitled.
  assert.equal(hooks.launchEntitled({ status: "past_due", plan: "supporter", current_period_end: past }), false);
});

// ── billing status/period surfacing (finding 3): no raw "Past_due" echo ──────

test("billingStatusLabel: past_due is a human dunning label, never 'Past_due'", () => {
  assert.equal(hooks.billingStatusLabel({ status: "past_due" }), "Payment past due");
  assert.equal(hooks.billingStatusLabel({ status: "canceled" }), "Canceled");
  assert.equal(hooks.billingStatusLabel({ status: "active", cancel_at_period_end: true }), "Cancels at period end");
  assert.equal(hooks.billingStatusLabel({ status: "active" }), "Active");
});

test("billingStatusBadge: compact status pill", () => {
  assert.equal(hooks.billingStatusBadge({ status: "past_due" }), "Past due");
  assert.equal(hooks.billingStatusBadge({ status: "active", cancel_at_period_end: true }), "Ending");
  assert.equal(hooks.billingStatusBadge({ status: "active" }), "Active");
});

test("billingPeriodLine: surfaces renewal / grace / cancel / end dates", () => {
  assert.match(hooks.billingPeriodLine({ status: "active", current_period_end: future }), /^Renews /);
  assert.match(hooks.billingPeriodLine({ status: "active", cancel_at_period_end: true, current_period_end: future }), /^Access until /);
  assert.match(hooks.billingPeriodLine({ status: "canceled", canceled_at: past }), /^Ended /);
  assert.equal(hooks.billingPeriodLine({ status: "active" }), ""); // no dated milestone
});

// ── cch-w54-s5 · THE PAST-DUE ARM IS DATELESS, AND IT IS DATELESS *HERE* ─────
//
// It used to read "Grace period ends {current_period_end}". mark_past_due/2
// re-anchors current_period_end to now+3d on every webhook delivery
// (billing.ex:827), so the quoted day slid forward each time a redelivery
// arrived, and nothing is scheduled to run when it lands — maybe_enforce/1's
// suspend arm is unreachable in production. The retraction lives INSIDE
// billingPeriodLine, which is what makes this test cover both twins: the owner
// card and the read-only member card call the same function.
const PERIOD_DATE_SHAPED =
  /\b(January|February|March|April|May|June|July|August|September|October|November|December)\b|\d{1,2}\/\d{1,2}|\d{4}-\d{2}-\d{2}/;

test("cch-w54-s5: billingPeriodLine's past-due arm names no day, and says what actually lapses", () => {
  const line = hooks.billingPeriodLine({ status: "past_due", current_period_end: future });
  assert.equal(line, "Grace period running — new instance launches stop when it ends");
  assert.doesNotMatch(line, PERIOD_DATE_SHAPED, "the past-due arm must not quote a sliding calendar day");
  assert.doesNotMatch(line, /Grace period ends/, "the retracted deadline promise must not come back");
  // A past-due sub with no dated milestone still gets the honest line — the
  // grace state is real whether or not the server sent an anchor.
  assert.equal(hooks.billingPeriodLine({ status: "past_due" }),
    "Grace period running — new instance launches stop when it ends");
});

// ── theme toggle label-in-name (WCAG 2.5.3): accessible name ⊇ visible word ──
// applyTheme() paints the visible label and the aria-label from these two pure
// helpers in lockstep. The invariant a screen-reader / voice-control user needs:
// whatever word is shown on the button is contained in its accessible name, in
// BOTH themes — so "click Dark" / "click Light" always resolves.

test("theme helpers are exported", () => {
  assert.equal(typeof hooks.themeLabelText, "function");
  assert.equal(typeof hooks.themeToggleAria, "function");
});

test("theme label shows the theme you'd switch TO, in each state", () => {
  assert.equal(hooks.themeLabelText("dark"), "Light");  // currently dark → offer Light
  assert.equal(hooks.themeLabelText("light"), "Dark");  // currently light → offer Dark
});

test("theme aria-label CONTAINS the visible word (label-in-name), both themes", () => {
  for (const t of ["dark", "light"]) {
    const visible = hooks.themeLabelText(t);       // "Light" | "Dark"
    const aria = hooks.themeToggleAria(t);         // "Switch to light theme" | "Switch to dark theme"
    assert.ok(
      aria.toLowerCase().includes(visible.toLowerCase()),
      `aria "${aria}" must contain visible word "${visible}"`,
    );
  }
  assert.equal(hooks.themeToggleAria("dark"), "Switch to light theme");
  assert.equal(hooks.themeToggleAria("light"), "Switch to dark theme");
});

// ── theme IDENTITY picker (D36) ─────────────────────────────────────────────
// data-bp-theme swaps the whole palette; it is a SECOND, orthogonal switch to
// the light/dark toggle above. normalizeBpTheme is the safety net: any id the
// build doesn't ship (stale localStorage, a retired theme) collapses to
// evergreen so a bad value never leaves the SPA on an undefined palette.

test("bp-theme picker helpers are exported", () => {
  assert.equal(typeof hooks.normalizeBpTheme, "function");
  assert.equal(typeof hooks.applyBpTheme, "function");
  assert.ok(Array.isArray(hooks.bpThemes));
});

test("bpThemes pins the GENERATED identity list — all 5 skins, in loadThemes order (GR12)", () => {
  // DELIBERATE update (gr-w3): BP_THEMES is now emitted from design/themes/*.json
  // (evergreen default first, then dir order), so charple + iris — the ids the old
  // hardcoded 3-list dropped, leaving charple emitted-but-unreachable — are present.
  // Regenerate via `node design/emit.mjs --write`; a drift reds design/check.mjs.
  assert.deepEqual([...hooks.bpThemes], ["evergreen", "charple", "ember", "fjord", "iris"]);
});

test("normalizeBpTheme passes known ids through and folds anything else to evergreen", () => {
  for (const id of ["evergreen", "charple", "ember", "fjord", "iris"]) {
    assert.equal(hooks.normalizeBpTheme(id), id);
  }
  // Unknown / hostile / empty inputs all fall back — never an undefined palette.
  for (const bad of ["", "EMBER", "midnight", null, undefined, "evergreen ", "0"]) {
    assert.equal(hooks.normalizeBpTheme(bad), "evergreen", `${JSON.stringify(bad)} → evergreen`);
  }
});

test("applyBpTheme returns the applied (normalized) id — the DOM stamp is no-op in the sandbox", () => {
  // document.documentElement.setAttribute + $("#bp-theme-picker") are inert here;
  // the return value is the contract the wiring persists to localStorage.
  assert.equal(hooks.applyBpTheme("ember"), "ember");
  assert.equal(hooks.applyBpTheme("fjord"), "fjord");
  assert.equal(hooks.applyBpTheme("evergreen"), "evergreen");
  assert.equal(hooks.applyBpTheme("bogus"), "evergreen");
});

// ════════════════════════════════════════════════════════════════════════════
// C3 — provisioning timeline: ONE fold (provisionSteps), THREE mounts.
// ════════════════════════════════════════════════════════════════════════════

test("C3: the timeline builders + mount seam are exported", () => {
  for (const name of ["provisionSteps", "stepElapsed", "fmtDur", "provisionTotalMs",
    "provisionChip", "newStepsHtml", "timelineHtml", "consoleTail",
    "instanceTimelineHtml", "mountInstanceTimeline"]) {
    assert.equal(typeof hooks[name], "function", name + " must be exported");
  }
});

// A fixed clock so elapsed math is deterministic. Steps stamp seconds past T0.
const T = (s) => "2026-07-03T12:00:0" + s + "Z";
const NOW = Date.parse("2026-07-03T12:00:10Z"); // T0 + 10s
const norm = (r) => ({
  step: r.step, label: r.label, role: r.role,
  elapsedMs: r.elapsedMs, caption: r.caption, probes: [...r.probes],
});

// ── stepElapsed + fmtDur: total-over-partial, never NaN ─────────────────────

test("stepElapsed: clean spans, and null (never NaN) on any missing/garbled stamp", () => {
  assert.equal(hooks.stepElapsed(T(0), T(2)), 2000);
  assert.equal(hooks.stepElapsed(1000, 3000), 2000);      // epoch-ms args
  assert.equal(hooks.stepElapsed(5000, 3000), 0);          // clamped, never negative
  assert.equal(hooks.stepElapsed(null, NOW), null);        // missing start
  assert.equal(hooks.stepElapsed(T(0), null), null);       // missing end
  assert.equal(hooks.stepElapsed("not-a-date", NOW), null);// garbled
  assert.ok(!Number.isNaN(hooks.stepElapsed("x", "y")));   // the invariant
});

test("fmtDur: —/seconds/minutes (pre-A4 arms byte-identical)", () => {
  assert.equal(hooks.fmtDur(null), "—");
  assert.equal(hooks.fmtDur(NaN), "—");
  assert.equal(hooks.fmtDur(500), "0s");
  assert.equal(hooks.fmtDur(42000), "42s");
  assert.equal(hooks.fmtDur(102000), "1m 42s");
  assert.equal(hooks.fmtDur(60000), "1m 0s");
  assert.equal(hooks.fmtDur(59000), "59s");   // last second before the minute arm
  assert.equal(hooks.fmtDur(3599000), "59m 59s"); // last second before the hour arm
});

test("fmtDur: A4 hour arm (≥60m) reads '2h 1m'", () => {
  assert.equal(hooks.fmtDur(3600000), "1h 0m");          // exactly 60m
  assert.equal(hooks.fmtDur(2 * 3600000 + 60000), "2h 1m");
  assert.equal(hooks.fmtDur(3 * 3600000 + 59 * 60000), "3h 59m");
});

// ── provisionSteps: the table test over every fixture the slice must handle ──

test("provisionSteps: empty (legacy row) → the five PLANNED steps pending (freshen + content are conditional, hidden until reported)", () => {
  const rows = hooks.provisionSteps({ provision_steps: [] }, NOW);
  assert.equal(rows.length, 5);
  // freshen (fallback rebuild) AND content (template bootstrap, skipped when the
  // job carries no template) are OPTIONAL — an unreported conditional step never
  // renders as a planned phase (it would hang pending forever). The verify gate
  // slots wherever content lands (or directly after configure when there's none).
  assert.deepEqual([...rows.map((r) => r.step)], ["create", "secure", "configure", "verify", "ready"]);
  assert.equal(rows[3].label, "Testing login & Studio"); // D45 label
  for (const r of rows) {
    assert.equal(r.role, "pending");
    assert.equal(r.elapsedMs, null);
    assert.equal(r.caption, "");
    assert.deepEqual([...r.probes], []);
  }
  // Total over junk: null bp never throws.
  assert.equal(hooks.provisionSteps(null, NOW).length, 5);
  assert.equal(hooks.provisionSteps(undefined).length, 5);
});

test("provisionSteps: a REPORTED content renders in place between configure and verify (a templated launch)", () => {
  const rows = hooks.provisionSteps({ provision_steps: [
    { step: "configure", status: "done", at: T(2) },
    { step: "content", status: "started", at: T(3) },
  ] }, NOW);
  assert.ok([...rows.map((r) => r.step)].includes("content"));
  const content = rows.filter((r) => r.step === "content")[0];
  assert.equal(content.label, "Installing your content");
  assert.equal(content.role, "active");
});

test("provisionSteps: a REPORTED freshen renders in place between create and secure (the fallback fired)", () => {
  const rows = hooks.provisionSteps({ provision_steps: [
    { step: "create", status: "started", at: T(0) },
    { step: "create", status: "done", at: T(2) },
    { step: "freshen", status: "started", at: T(2) },
  ] }, NOW);
  // content stays hidden (unreported); freshen slots in because it WAS reported.
  assert.deepEqual([...rows.map((r) => r.step)], ["create", "freshen", "secure", "configure", "verify", "ready"]);
  assert.equal(rows[1].label, "Updating to the latest Barkpark"); // dwb-17 freshen label
  assert.equal(rows[1].role, "active");
});

test("provisionSteps: partial (mid-configure) — done/done/active/pending…", () => {
  const bp = { provision_steps: [
    { step: "create", status: "started", at: T(0) },
    { step: "create", status: "done", at: T(2) },
    { step: "secure", status: "started", at: T(2) },
    { step: "secure", status: "done", at: T(4) },
    { step: "configure", status: "started", at: T(5), detail: "Installing packages" },
  ] };
  const rows = hooks.provisionSteps(bp, NOW);
  assert.deepEqual(norm(rows[0]), { step: "create", label: "Creating your server", role: "ok", elapsedMs: 2000, caption: "", probes: [] });
  // Unstarted freshen is HIDDEN (fallback step) — secure follows create directly.
  assert.deepEqual(norm(rows[1]), { step: "secure", label: "Securing your domain", role: "ok", elapsedMs: 2000, caption: "", probes: [] });
  assert.deepEqual(norm(rows[2]), { step: "configure", label: "Configuring Barkpark", role: "active", elapsedMs: 5000, caption: "Installing packages", probes: [] });
  // content unreported → hidden; verify + ready follow configure directly.
  assert.equal(rows[3].step, "verify");
  assert.equal(rows[3].role, "pending"); // verify still upcoming
  assert.equal(rows[4].step, "ready");
  assert.equal(rows[4].role, "pending"); // ready last
  assert.equal(rows.length, 5);
});

test("provisionSteps: verify with probe lines → checklist under the step", () => {
  const bp = { provision_steps: [
    { step: "verify", status: "started", at: T(5), detail: "Probing the golden path" },
    { step: "verify", status: "progress", at: T(6), detail: "verify.login: 200 in 120ms" },
    { step: "verify", status: "progress", at: T(7), detail: "verify.query: 200 in 42ms" },
  ] };
  const verify = hooks.provisionSteps(bp, NOW)[3]; // freshen + content hidden (unreported) → verify at index 3
  assert.equal(verify.role, "active");
  assert.equal(verify.caption, "Probing the golden path");   // the started narration
  assert.deepEqual([...verify.probes], ["verify.login: 200 in 120ms", "verify.query: 200 in 42ms"]);
  assert.equal(verify.elapsedMs, 5000); // NOW - T5
});

