// ── S13 `unknown`: a rung the control plane could not MEASURE ────────────────
// The server stopped folding five resolver faults into "no A/AAAA record has
// propagated yet" + "give it a moment and re-check". The SPA must fold the new
// state in the SAME commit, or the fix is a no-op PLUS a regression: `unknown`
// would land in the else-branch and paint the identical WAITING grammar, still
// show remediation, and keep the 4s poll running against a dead resolver.
// The envelope below is NOT hand-authored — it is the REAL check/2 output from
// the shared, drift-gated fixture (its fourth scenario).
const DOMAIN_RESOLVER_FAULTED = DOMAIN_FIXTURE.resolver_faulted;

test("S13: an unmeasured rung folds to its OWN role — never the waiting grammar", () => {
  const m = hooks.domainStages(DOMAIN_RESOLVER_FAULTED, 0);
  const d = m.domains[0];
  // The server's own shape: the ATTEMPTED rung is unknown, the three it skipped
  // stay pending (containment) — and NOT ONE of them is promoted to "active",
  // because nothing behind an unmeasurable rung is in progress.
  assert.deepEqual([...d.rows.map((r) => r.role)], ["unknown", "pending", "pending", "pending"]);
  assert.equal(d.overallRole, "unknown");
  assert.equal(d.overall, "unknown");
  assert.equal(m.ok, false);
  // PRE-FIX these were: role "pending" (the waiting grammar), overallRole
  // "pending", the tls rung promoted to "active" — the console telling the
  // person to wait for a check nobody made.
  assert.notEqual(d.rows[0].role, "pending");
  assert.notEqual(d.overallRole, "pending");
});

test("S13: an unknown rung shows NO remediation — even if a server sends one", () => {
  const m = hooks.domainStages(DOMAIN_RESOLVER_FAULTED, 0);
  const dns = m.domains[0].rows[0];
  assert.equal(dns.role, "unknown");
  assert.equal(dns.showRemediation, false);
  assert.equal(dns.remediation, ""); // the server sends null; the fold coerces it
  // The honest copy is the EVIDENCE, and it never claims anything about the
  // person's records.
  assert.match(dns.evidence, /Could not check whether/);
  assert.ok(dns.evidence.indexOf("has propagated yet") === -1);
  // Defense in depth: a stale/rogue server that DOES attach advice to an
  // unmeasured rung still renders none — advice about a check nobody made is
  // the defect itself.
  const rogue = hooks.domainStageRows([
    { stage: "dns_found", label: "DNS resolves", status: "unknown", evidence: "lookup failed", remediation: "Give it a moment and re-check." },
  ]);
  assert.equal(rogue[0].role, "unknown");
  assert.equal(rogue[0].showRemediation, false);
  const html = hooks.domainChecklistHtml(hooks.domainStages(DOMAIN_RESOLVER_FAULTED, 0), {});
  assert.ok(html.indexOf("dom-note") === -1, "an unknown-fronted host renders no amber advice note");
  assert.match(html, /dom-rung--unknown/);
});

test("S13: an unmeasurable host is TERMINAL — the 4s poll stops asking a dead resolver", () => {
  const m = hooks.domainStages(DOMAIN_RESOLVER_FAULTED, 0);
  assert.equal(m.terminal, true);
  // PRE-FIX: false — every trailing skipped-pending rung kept the mount polling
  // every 4s forever against a resolver that cannot answer.
  // The narrowness guard: an unknown rung settles ONLY its own host. A second,
  // still-issuing host in the same envelope keeps the whole model polling.
  const mixed = hooks.domainStages({
    ok: false,
    domains: [
      DOMAIN_RESOLVER_FAULTED.domains[0],
      DOMAIN_PENDING.domains[0],
    ],
  }, 0);
  assert.equal(mixed.terminal, false);
  assert.equal(mixed.domains[0].overallRole, "unknown");
  assert.equal(mixed.domains[1].overallRole, "pending");
});

test("S13: the status→role map is a CLOSED ENUM — an unrecognised status never lands in a known bucket", () => {
  const rows = hooks.domainStageRows([
    { stage: "dns_found", status: "ok" },
    { stage: "points_here", status: "quantum" },     // a status this SPA has never heard of
    { stage: "tls", status: "" },                    // absent status
    { stage: "serving", status: "PENDING" },         // case is NOT normalised — not the enum value
  ]);
  // None of them silently becomes ok / failed / proxied / pending / active.
  assert.deepEqual([...rows.slice(1).map((r) => r.role)], ["unknown", "unknown", "unknown"]);
  // The raw status is preserved verbatim for display (the CLI's statusDash
  // discipline: pass it through scrubbed, never guess what it meant).
  assert.deepEqual([...rows.slice(1).map((r) => r.status)], ["quantum", "", "PENDING"]);
  // And the same closed enum governs the roll-up.
  const roll = (overall) => hooks.domainStages({ domains: [{ host: "h", overall: overall, stages: [] }] }, 0).domains[0].overallRole;
  assert.equal(roll("ok"), "ok");
  assert.equal(roll("failed"), "failed");
  assert.equal(roll("pending"), "pending");
  assert.equal(roll("unknown"), "unknown");
  assert.equal(roll("sideways"), "unknown");
  assert.equal(roll(""), "unknown");
});

// ── cch-w29: the RENDER layer of an unmeasurable rung ───────────────────────
// cch-w28-s7 gave `unknown` its own role in the pure fold and stopped there
// (D326 anchor discipline), so domainRungChip still fell through to the waiting
// dot and the word "waiting". Three channels lied and the fourth was inert; the
// one existing assertion pinned only the class, which was never broken.
//
// EVERY ASSERTION BELOW IS A POSITIVE STRING PIN. The pre-fix criterion was a
// NEGATIVE ("the state word is not 'waiting'"), which the mutation state →
// "done" satisfies while telling a screen-reader user an UNMEASURABLE rung is
// FINISHED — a worse lie that shipped green.

test("cch-w29: an unmeasurable rung's ACCESSIBLE NAME says we could not check it", () => {
  const m = hooks.domainStages(DOMAIN_RESOLVER_FAULTED, 0);
  const chip = hooks.domainRungChip(m.domains[0].rows[0]);
  // The exact words a screen reader speaks. PRE-FIX: "DNS resolves — waiting".
  assert.match(chip, /aria-label="DNS resolves — could not check"/);
  // ABLE TO LOSE against the two known mutations, positively:
  //   state → "waiting" (the shipped defect) and state → "done" (the mutation
  //   the old negative criterion accepted) both break the line above.
  assert.ok(chip.indexOf('aria-label="DNS resolves — waiting"') === -1);
  assert.ok(chip.indexOf('aria-label="DNS resolves — done"') === -1);
});

test("cch-w29: an unmeasurable rung's GLYPH is its own — not the waiting dot, not the settled circle", () => {
  const m = hooks.domainStages(DOMAIN_RESOLVER_FAULTED, 0);
  const chip = hooks.domainRungChip(m.domains[0].rows[0]);
  assert.match(chip, /<span class="dom-rung-glyph" aria-hidden="true">&#63;<\/span>/);
  // The two glyphs it must never wear: `&middot;` (a rung we ARE waiting on)
  // and `&#9679;` (reserved for the settled ok/proxied rungs).
  assert.ok(chip.indexOf("&middot;") === -1);
  assert.ok(chip.indexOf("&#9679;") === -1);
  // The neighbouring arms keep their glyphs — this is an added arm, not a
  // re-map (a settled rung must still read as settled).
  const ok = hooks.domainRungChip({ label: "TLS certificate", role: "ok", evidence: "" });
  assert.match(ok, /aria-hidden="true">&#9679;</);
  assert.match(ok, /aria-label="TLS certificate — done"/);
});

test("cch-w29: the rungs BEHIND an unmeasurable one say 'not checked', never 'waiting'", () => {
  // The server's own evidence for these three reads "Not checked yet — an
  // earlier step couldn't be checked", while the chip announced "waiting" —
  // the console promising motion on a host nothing is measuring.
  const m = hooks.domainStages(DOMAIN_RESOLVER_FAULTED, 0);
  const html = hooks.domainChecklistHtml(m, {});
  assert.match(html, /aria-label="Points to this instance — not checked"/);
  assert.match(html, /aria-label="TLS certificate — not checked"/);
  assert.match(html, /aria-label="Serving traffic — not checked"/);
  assert.ok(html.indexOf(" — waiting\"") === -1, "no rung on an unmeasurable host announces waiting");
  // Containment: a genuinely-pending host (nothing unknown) KEEPS the waiting
  // grammar — that one really is queued, and this must not become a blanket
  // rename.
  const pending = hooks.domainChecklistHtml(hooks.domainStages(DOMAIN_PENDING, 0), {});
  assert.match(pending, / — waiting"/);
});

test("cch-w29: .dom-rung--unknown is PAINTED — an unmeasurable pill is not pixel-identical to a waiting one", () => {
  const css = fs.readFileSync(new URL("./app.css", import.meta.url), "utf8");
  const rule = css.match(/\.dom-rung--unknown\s*\{([^}]*)\}/);
  assert.ok(rule, "app.css must carry a `.dom-rung--unknown` rule (it carried NONE — grep -c was 0)");
  // Tokens only: a raw colour here reds design/emit-fence.test.mjs' neighbours.
  assert.ok(!/#[0-9a-fA-F]{3,8}\b/.test(rule[1]), "the unknown rung paints from tokens, never a raw hex");
  assert.match(rule[1], /var\(--warn/);
  // And it differs from the default (waiting) .dom-rung base pill.
  const base = css.match(/\n\.dom-rung\s*\{([^}]*)\}/);
  assert.ok(base, "app.css must still carry the base `.dom-rung` rule");
  assert.notEqual(rule[1].trim(), base[1].trim());
});

test("cch-w29: a TERMINAL unmeasurable rail offers a re-check — derived in the pure fold", () => {
  const m = hooks.domainStages(DOMAIN_RESOLVER_FAULTED, 0);
  assert.equal(m.terminal, true);
  assert.equal(m.recheckable, true);
  const html = hooks.domainChecklistHtml(m, {});
  assert.match(html, /<button class="btn btn-sm" type="button" data-dom-recheck>Check again<\/button>/);
  assert.match(html, /stopped updating on their own/);

  // Only when the poll actually stopped for a reason a retry can fix:
  //  - a still-issuing host is NON-terminal (the 4s poll IS the affordance)
  const mid = hooks.domainStages(DOMAIN_PENDING, 0);
  assert.equal(mid.recheckable, false);
  assert.ok(hooks.domainChecklistHtml(mid, {}).indexOf("data-dom-recheck") === -1);
  //  - a fully-settled host is terminal but has nothing left to re-ask
  const done = hooks.domainStages(DOMAIN_FIXTURE.all_serving, 0);
  assert.equal(done.terminal, true);
  assert.equal(done.recheckable, false);
  assert.ok(hooks.domainChecklistHtml(done, {}).indexOf("data-dom-recheck") === -1);
  //  - and the EMPTY early return stays the bare rail row: a re-check over a
  //    host with no attached domains is an affordance for nothing.
  const empty = hooks.domainStages({ ok: true, domains: [] }, 0);
  assert.equal(empty.empty, true);
  assert.ok(hooks.domainChecklistHtml(empty, { custom_host: "" }).indexOf("data-dom-recheck") === -1);
});

test("cch-w29: BOTH mounts re-bind the re-check after their innerHTML paint", () => {
  // app.js has no delegated dispatcher and both mounts repaint with
  // `innerHTML` (which destroys listeners), so a bind that happens once at boot
  // is a dead control. Pin that each mount queries the button AFTER its own
  // paint and calls ITS OWN loader.
  const src = fs.readFileSync(new URL("./app.js", import.meta.url), "utf8");
  for (const [mount, loader] of [["loadInstanceDomains", "loadInstanceDomains"], ["loadSiteDomains", "loadSiteDomains"]]) {
    const body = src.slice(src.indexOf("function " + mount + "("));
    const paint = body.indexOf("b.innerHTML");
    const bind = body.indexOf('b.querySelector("[data-dom-recheck]")');
    assert.ok(paint !== -1 && bind !== -1, mount + " must paint and then bind the re-check");
    assert.ok(bind > paint, mount + " binds [data-dom-recheck] BEFORE its paint — innerHTML would drop it");
    const handler = body.slice(bind, bind + 400);
    assert.ok(handler.indexOf('addEventListener("click"') !== -1, mount + "'s re-check must be clickable");
    assert.ok(handler.indexOf(loader + "(") !== -1, mount + "'s re-check must re-run " + loader);
  }
});

test("cch-w29 (review): a re-check that FAILED restores its own button — never a dead 'Checking…'", () => {
  // The click disables the button and relabels it "Checking…", and BOTH mounts
  // return early on 404/error WITHOUT repainting. Unrestored, the only way back
  // from a terminal unmeasurable rail sat permanently disabled announcing work
  // nobody was doing — this epic's own defect class, one control over.
  const src = fs.readFileSync(new URL("./app.js", import.meta.url), "utf8");
  const helper = src.slice(src.indexOf("function restoreDomainRecheck("));
  assert.ok(helper.indexOf("again.disabled = false") !== -1, "the helper must re-enable the button");
  assert.ok(helper.indexOf('again.textContent = "Check again"') !== -1, "and restore its ORIGINAL label, not leave 'Checking…'");
  assert.ok(helper.indexOf(".dom-recheck-note") !== -1, "and say what happened, rather than silently reverting");
  for (const mount of ["loadInstanceDomains", "loadSiteDomains"]) {
    const body = src.slice(src.indexOf("function " + mount + "("));
    const bail = body.indexOf("if (!r.ok || !r.data)");
    const paint = body.indexOf("b.innerHTML");
    assert.ok(bail !== -1, mount + " must still bail on 404/error");
    assert.ok(bail < paint, mount + "'s bail must precede its paint");
    assert.ok(
      body.slice(bail, paint).indexOf("restoreDomainRecheck(b)") !== -1,
      mount + " returns early on 404/error without restoring the re-check it disabled",
    );
  }
});

// ─────────────────────────────────────────────────────────────────────────────
// S12 (azure-hetzner hosting): the Metrics tab — metricsSeries fold + the
// string-returning SVG sparkline. Consumers NEVER compute; they render the
// pinned S12a envelope verbatim.
// ─────────────────────────────────────────────────────────────────────────────

const METRICS_LIVE = {
  ok: true,
  collected_at: "2026-07-09T12:00:00Z",
  instance: { id: "bp_1", host: "prod.barkpark.cloud", provider: "hetzner" },
  beat: { last_seen_at: "2026-07-09T11:59:30Z", age_seconds: 30, status: "live" },
  points: 4,
  series: {
    cpu: [{ at: "t0", value: 12 }, { at: "t1", value: 44 }, { at: "t2", value: 30 }, { at: "t3", value: 55 }],
    mem: [{ at: "t0", value: 60 }, { at: "t1", value: 62 }, { at: "t2", value: 61 }, { at: "t3", value: 63 }],
    disk: [{ at: "t0", value: 40 }, { at: "t1", value: 40 }, { at: "t2", value: 41 }, { at: "t3", value: 41 }],
    load: [{ at: "t0", value: 0.5 }, { at: "t1", value: 1.2 }, { at: "t2", value: 0.8 }, { at: "t3", value: 1.1 }],
  },
  service_health: { pass: 3, total: 3, failing: [] },
};

test("S12: metricsSeries folds a live envelope — status, current, host/provider, health", () => {
  const m = hooks.metricsSeries(METRICS_LIVE);
  assert.equal(m.status, "live");
  assert.equal(m.live, true);
  assert.equal(m.absent, false);
  assert.equal(m.stale, false);
  assert.equal(m.host, "prod.barkpark.cloud");
  assert.equal(m.provider, "hetzner");
  assert.deepEqual([...m.metrics.map((x) => x.key)], [...hooks.metricsKeys]);
  const cpu = m.metrics.find((x) => x.key === "cpu");
  assert.equal(cpu.current, 55); // latest non-null value
  assert.equal(cpu.hasData, true);
  assert.deepEqual([...cpu.values], [12, 44, 30, 55]);
  assert.equal(m.health.pass, 3);
  assert.equal(m.health.total, 3);
  assert.deepEqual([...m.health.failing], []);
  assert.equal(hooks.metricsValueText(cpu), "55%");
  const load = m.metrics.find((x) => x.key === "load");
  assert.equal(hooks.metricsValueText(load), "1.1"); // no unit, two-decimal max
});

test("S12: metricsSeries — absent beat yields the honest waiting state (never a zeroed chart)", () => {
  const m = hooks.metricsSeries({ ok: true, beat: { status: "absent" }, series: {} });
  assert.equal(m.absent, true);
  const html = hooks.metricsPanelHtml(m);
  assert.match(html, /Waiting for the first beat/);
  // No chart is drawn in the absent state.
  assert.ok(html.indexOf("metrics-grid") === -1);
  assert.ok(html.indexOf("<svg") === -1);
});

test("S12: metricsSeries — stale beat flags the last-known series with 'last seen Xm ago'", () => {
  const stale = { ...METRICS_LIVE, beat: { last_seen_at: "t", age_seconds: 180, status: "stale" } };
  const m = hooks.metricsSeries(stale);
  assert.equal(m.stale, true);
  assert.equal(m.lastSeenText, "3m ago"); // 180s → 3m
  const html = hooks.metricsPanelHtml(m);
  assert.match(html, /Agent offline/);
  assert.match(html, /last seen 3m ago/);
  // The last-known series is STILL rendered (a stale read shows history, not blank).
  assert.match(html, /metrics-grid/);
  assert.match(html, /<svg/);
});

test("S12: metricsAgeText — honest human ages, garbage → ''", () => {
  assert.equal(hooks.metricsAgeText(0), "0s ago");
  assert.equal(hooks.metricsAgeText(45), "45s ago");
  assert.equal(hooks.metricsAgeText(90), "1m ago");
  assert.equal(hooks.metricsAgeText(3600), "1h ago");
  assert.equal(hooks.metricsAgeText(90000), "1d ago");
  for (const bad of [null, undefined, NaN, -5, "x"]) assert.equal(hooks.metricsAgeText(bad), "");
});

test("S12: metricsSeries preserves null points as gaps (a null never becomes 0) + current skips trailing nulls", () => {
  const holey = {
    ok: true, beat: { status: "live", age_seconds: 10 },
    series: { cpu: [{ at: "t0", value: 10 }, { at: "t1", value: null }, { at: "t2", value: 20 }, { at: "t3", value: null }] },
  };
  const m = hooks.metricsSeries(holey);
  const cpu = m.metrics.find((x) => x.key === "cpu");
  // The null is preserved as null in the values array — NOT coerced to 0.
  assert.deepEqual([...cpu.values], [10, null, 20, null]);
  // current is the latest REAL value, skipping the trailing null.
  assert.equal(cpu.current, 20);
});

test("S12: metricsSeries is TOTAL — a null/garbage payload never throws", () => {
  for (const bad of [null, undefined, {}, { series: null }, { beat: 7, series: { cpu: [null, {}, { value: "x" }] } }]) {
    const m = hooks.metricsSeries(bad);
    assert.equal(typeof m.status, "string");
    assert.equal(Array.isArray(m.metrics), true);
    assert.equal(m.metrics.length, hooks.metricsKeys.length);
    // A garbage / absent beat degrades to the absent state, never a crash.
    assert.equal(["live", "stale", "absent"].includes(m.status), true);
  }
  // A bogus cpu series (non-numeric samples) → all-null values, hasData false.
  const m = hooks.metricsSeries({ beat: { status: "live" }, series: { cpu: [{ value: "x" }, null] } });
  const cpu = m.metrics.find((x) => x.key === "cpu");
  assert.deepEqual([...cpu.values], [null, null]);
  assert.equal(cpu.hasData, false);
  assert.equal(cpu.current, null);
  assert.equal(hooks.metricsValueText(cpu), "—"); // holes-only → em-dash, never a fake 0
});

test("S12: sparklineSvg draws a NULL as a gap, not a point at the baseline", () => {
  // [10, null, 20]: two isolated islands → two dots, ZERO connecting polyline, and
  // exactly two plotted points (the non-null count) — the null draws nothing.
  const svg = hooks.sparklineSvg([10, null, 20], { width: 100, height: 40 });
  assert.match(svg, /^<svg[\s\S]*<\/svg>$/);
  assert.equal((svg.match(/<circle/g) || []).length, 2);
  assert.equal((svg.match(/<polyline/g) || []).length, 0);
  assert.ok(svg.indexOf("NaN") === -1, "no NaN coordinates leak");

  // [10,20,null,30,40]: two runs → two polylines, four total plotted points.
  const svg2 = hooks.sparklineSvg([10, 20, null, 30, 40], { width: 100, height: 40 });
  const polys = svg2.match(/points="([^"]*)"/g) || [];
  assert.equal(polys.length, 2); // one polyline per contiguous run (the null is the gap)
  const pairs = polys.reduce((acc, p) => acc + p.replace(/points="|"/g, "").trim().split(/\s+/).length, 0);
  assert.equal(pairs, 4); // exactly the four real samples — the null contributes none
});

test("S12: sparklineSvg — empty / all-null → an empty frame (never a fabricated line)", () => {
  for (const vals of [[], [null, null], null, undefined, ["x", NaN]]) {
    const svg = hooks.sparklineSvg(vals, {});
    assert.match(svg, /^<svg[\s\S]*<\/svg>$/);
    assert.ok(svg.indexOf("<polyline") === -1);
    assert.ok(svg.indexOf("<circle") === -1);
  }
});

test("S12: sparklineSvg — a flat series draws along the mid-line, never at y=0 (no divide-by-zero)", () => {
  const h = 40, pad = 3;
  const svg = hooks.sparklineSvg([50, 50, 50, 50], { width: 100, height: h });
  const poly = (svg.match(/points="([^"]*)"/) || [])[1];
  assert.ok(poly, "a flat series still draws a stroke");
  const ys = poly.trim().split(/\s+/).map((p) => Number(p.split(",")[1]));
  const mid = pad + (h - pad * 2) / 2;
  for (const y of ys) assert.equal(y, mid); // mid-line baseline, not the y=0 top edge
});

test("S12: metricsHealthHtml — failing checks surface; absent counts hide (never 0/0)", () => {
  assert.equal(hooks.metricsHealthHtml({}), "");
  assert.equal(hooks.metricsHealthHtml({ pass: 0, total: 0, failing: [] }), "");
  const ok = hooks.metricsHealthHtml({ pass: 3, total: 3, failing: [] });
  assert.match(ok, /Health 3\/3/);
  const bad = hooks.metricsHealthHtml({ pass: 2, total: 3, failing: ["disk", "http"] });
  assert.match(bad, /Health 2\/3/);
  assert.match(bad, /failing: disk, http/);
});

// D-07 (GR27): the request-level stubs are honest dashed rows — WHAT, never a
// fabricated number and never the 24h-warmup ETA fiction (GR28).
