// ─────────────────────────────────────────────────────────────────────────────
// cch-w14-s2 — THE FOLDED SHELL STOPS OPENING EVERY SCREEN ON 746px OF NAV.
// The defect and the fix are both GEOMETRY, so the proof that matters is driven
// in a real browser (72 cells, both themes, three route families: `.content` top
// went 745.88 -> 328 at h=800 and -> 282.77 at h=667, while 721 and 768 stayed at
// exactly 56). What these tests own is the smaller thing a node run CAN own —
// the source-level invariants that, if any one silently reverted, would put the
// wall back while every browser proof still read green in a paper.
// ─────────────────────────────────────────────────────────────────────────────

test("cch-w14-s2: the folded shell CAPS the nav strip and CUES the clip (never a bare cap)", () => {
  const css = fs.readFileSync(new URL("./app.css", import.meta.url), "utf8");
  // app.css carries several 720 blocks; the SHELL FOLD is the one that turns
  // .app-shell into a column. Anchored on that declaration, never on ordinal.
  const anchor = css.indexOf(".app-shell { flex-direction: column; }");
  assert.ok(anchor > 0, "the shell-fold block must exist");
  const at = css.lastIndexOf("@media (max-width: 720px)", anchor);
  assert.ok(at > 0 && anchor - at < 200, "the fold must still be the 720px block");
  const block = css.slice(at, css.indexOf("\n}\n", at) + 3);
  // cch-w15-s1: the cap subtracts the invariant 56px topbar so contentTop is
  // 0.4H - 4 at EVERY height. A bare `Nvh` cap is `N + 56/H` and is worst at the
  // smallest height, which is how 34vh sat over the sweep's own 0.4 bar at all of
  // 800/667/390 while a 745.88px pin reported it green.
  assert.match(block, /max-height:\s*calc\(40vh - 60px\)/, "the folded strip must be capped by a topbar-cancelling calc (it stood 690px tall; a bare vh cap drifts with height)");
  assert.match(block, /overflow-y:\s*auto/, "a cap with no scroller strands the rest of the nav");
  // A cap with no continuation cue is the W12 clipped-without-cue defect wearing
  // a new hat, which is why these travel together and neither may ship alone.
  assert.match(block, /mask-image:\s*linear-gradient\(to bottom/, "the clip must be CUED");
  assert.match(block, /\.sidebar\.is-nav-clipped\s*\{\s*--nav-fade:\s*40px/, "the cue is live iff clipped");
  assert.match(css, /@property --nav-fade/, "--nav-fade must be REGISTERED or the fade jumps");
  // D153: the fold itself is NOT raised — raising it relocates the same cliff
  // onto every tablet in portrait. The `anchor - at < 200` check above is that
  // assertion: the column-stack lives inside the 720 block and nowhere else, and
  // exactly one rule in the file stacks the shell.
  assert.equal(css.split(".app-shell { flex-direction: column; }").length - 1, 1,
    "exactly one rule may stack the shell, and it is the 720px fold");
});

test("cch-w14-s2: Settings is a real <details> disclosure, and the dead .nav-menu idiom is gone", () => {
  const html = fs.readFileSync(new URL("./index.html", import.meta.url), "utf8");
  const css = fs.readFileSync(new URL("./app.css", import.meta.url), "utf8");
  const js = fs.readFileSync(new URL("./app.js", import.meta.url), "utf8");
  assert.match(html, /<details class="nav-group" id="nav-settings" open>/,
    "a native disclosure — aria-expanded, Enter/Space and the open state come free");
  assert.match(html, /<summary class="nav-eyebrow nav-group-summary">/);
  assert.match(js, /function syncNavDisclosure\(onRoute\)/);
  assert.match(js, /group\.querySelector\("\.nav-link\.is-active"\)/,
    "the active Settings screen must never be sealed behind a closed summary");
  // The pre-v4 topbar dropdown retires in the SAME commit, CSS and JS both —
  // half a retirement is how it survived the whole v4 shell in the first place.
  assert.ok(!/\bnav-menu\b/.test(html), "index.html must not carry the retired idiom");
  assert.ok(!/^\s*\.nav-menu[\s{,[:]/m.test(css), "no live .nav-menu rule may remain");
  assert.ok(!/querySelector\([^)]*nav-menu/.test(js), "no JS may still sweep for .nav-menu");
});

test("cch-w14-s2: the clip cue is driven from a MEASURED state, on every trigger that changes it", () => {
  const js = fs.readFileSync(new URL("./app.js", import.meta.url), "utf8");
  assert.match(js, /sb\.scrollHeight - sb\.clientHeight - sb\.scrollTop/,
    "the cue reads live geometry — inferring it from a scroll timeline measured dead on 48 of 72 cells");
  assert.match(js, /classList\.toggle\("is-nav-clipped", below > 1\)/);
  // Five triggers. Lose any one and the cue goes silent on some route.
  for (const trigger of [
    /sb\.addEventListener\("scroll", navStripCue/,
    /window\.addEventListener\("resize", function \(\) \{ syncNavDisclosure\(false\); \}\)/,
    /group\.addEventListener\("toggle", navStripCue\)/,
    /new window\.ResizeObserver\(function \(\) \{ syncNavDisclosure\(false\); \}\)/,
    /syncNavDisclosure\(true\);/,
  ]) assert.match(js, trigger, "missing a navStripCue trigger: " + trigger);
  // A geometry event must NOT re-apply the collapse rule unless the fold itself
  // was crossed — otherwise a person's own tap on Settings snaps it shut again.
  assert.match(js, /if \(!onRoute && !crossed\) \{ navStripCue\(\); return; \}/,
    "a resize that did not cross the fold must leave the person's disclosure choice alone");
});

// ── cch-w20-s3: the address as TEXT vs the address as a PAYLOAD ──────────────
// Appended at the END on purpose: node --test numbers tests positionally, and
// this wave's evidence cites existing numbers (658 is the copy-payload guard).
// Inserting anywhere above would renumber somebody else's proof.
test("cch-w20-s3: displayUrl shaves the scheme, publicUrl keeps it — and a custom host rides the same rule", () => {
  const bp = { url: "https://production-5b2c1e.barkpark.cloud" };
  assert.equal(hooks.publicUrl(bp), "https://production-5b2c1e.barkpark.cloud");
  assert.equal(hooks.displayUrl(bp), "production-5b2c1e.barkpark.cloud");
  // an attached custom host is THE address, and it is shaved the same way
  const custom = { url: "https://production-5b2c1e.barkpark.cloud", custom_host: "app.acme.no" };
  assert.equal(hooks.publicUrl(custom), "https://app.acme.no");
  assert.equal(hooks.displayUrl(custom), "app.acme.no");
  // http is shaved too (a self-hosted control plane), and only at the FRONT
  assert.equal(hooks.displayUrl({ url: "http://box.internal/https://x" }), "box.internal/https://x");
  // no address yet (provisioning) → the empty string, never "undefined"
  assert.equal(hooks.displayUrl({}), "");
  // a path is kept whole — the shave is the scheme, not a truncation
  assert.equal(hooks.displayUrl({ url: "https://acme.barkpark.cloud/sites/blog/" }), "acme.barkpark.cloud/sites/blog/");
  // REVIEW (wave 20): an uppercased scheme is shaved too. Nothing normalises
  // bp.url before render, and a case-SENSITIVE match would have painted the
  // scheme back on for that one record while every driven cell stayed green.
  assert.equal(hooks.displayUrl({ url: "HTTPS://production-5b2c1e.barkpark.cloud" }), "production-5b2c1e.barkpark.cloud");
  assert.equal(hooks.displayUrl({ custom_host: "app.acme.no", url: "HtTp://box.internal" }), "app.acme.no");
});

test("cch-w20-s3: BOTH text sites shave the scheme together — the card and the fleet row never disagree", () => {
  const bp = {
    id: "bp-1", name: "Production", slug: "production", url: "https://production-5b2c1e.barkpark.cloud",
    host: "production-5b2c1e.barkpark.cloud", health_status: "ok", agent_status: "online",
    version: "0.9.2", provision_status: "succeeded",
  };
  const row = hooks.fleetRow(bp);
  assert.match(row, /class="fleet-url">production-5b2c1e\.barkpark\.cloud</);
  assert.ok(row.indexOf('class="fleet-url">https://') === -1,
    "the fleet row must not keep the scheme while the card drops it — that split is the sin scenarios.mjs:2331 exists to prevent");
  // …while the PAYLOAD keeps the whole address: a person copying it needs the
  // scheme. This is the same guarantee test 658 (GR24) pins on the header.
  const header = hooks.instanceHeaderHtml(bp);
  assert.match(header, /data-copy="https:\/\/production-5b2c1e\.barkpark\.cloud"/);
  assert.match(header, /detail-url-text">https:\/\/production-5b2c1e\.barkpark\.cloud</);
  // the card's own site is source-pinned: instanceCardHtml is not exported, so
  // the browser guard (overflow-guard.mjs W18 leg) is what measures it live.
  const js = fs.readFileSync(new URL("./app.js", import.meta.url), "utf8");
  assert.match(js, /class="instance-card-url">' \+ esc\(displayUrl\(bp\)\)/);
  assert.match(js, /class="fleet-url">' \+ esc\(displayUrl\(bp\)\)/);
});

// ── cch-w22-s5: the console stops asserting false things ────────────────────
// TWO misinformation defects, NEITHER of which is about length — this pair is
// the wave's proof that CRUEL != LONG. (A) is 30 characters against a 160 cap;
// (B) needs no attacker at all, only a browser clock behind the server's.

const RLO = "\u202E"; // RIGHT-TO-LEFT OVERRIDE — scopes to end-of-paragraph
// NBSP is the separator, not a space: @email_format (accounts/user.ex:31) is
// ~r/^[^\s@]+@[^\s@]+$/ with NO `u` modifier, so its \s is ASCII-only and a
// U+00A0 sails through — which is what makes the whole payload a SERVER-LEGAL
// email rather than a thought experiment (proven with `elixir -e`, see the task).
const NB = "\u00A0";

test("cch-w22-s5 (A): esc() drops the bidi controls, so an actor email can no longer forge the audit verb", () => {
  // THE FORGERY. activityRow builds ONE text run: esc(who) + " " + esc(verb).
  // With an RLO in the email the browser painted `ops@acme.cometis a detaerc
  // created a site` — the words "created a site" reading correctly, LTR — on a
  // row whose record said site.deleted.
  // The decoy is the REAL ACTION_LABELS vocabulary, pre-reversed: "created a
  // site" backwards is "etis a detaerc".
  const evil = "ops@acme.com" + RLO + NB + "etis" + NB + "a" + NB + "detaerc";
  assert.equal(evil.length, 28, "the whole payload is 28 characters, against a 160-char email cap");
  const row = hooks.activityRow({
    actor: { email: evil }, action: "site.deleted", inserted_at: "2026-08-02T00:00:00Z",
  });
  assert.ok(!row.includes(RLO), "no bidi control survives into the markup");
  // The verb the RECORD carries is the verb the row now spells, uninterrupted.
  assert.match(row, /class="fleet-name">ops@acme\.com\u00A0etis\u00A0a\u00A0detaerc deleted a site/);
  // The pre-reversed decoy text is still THERE (nothing is censored) — it just
  // cannot reorder the system's words around it any more.
  assert.ok(row.includes("etis" + NB + "a" + NB + "detaerc"), "the attacker's own letters are not laundered away");

  // THE SECOND HOST, same commit: memberRowHtml's "(you)" self-marker used to
  // be swallowed by the same run — painted `mallory)uoy( moc.live@<RLO>`.
  const self = hooks.memberRowHtml(
    { user_id: "u1", email: RLO + "mallory@evil.com", role: "member", joined_at: "2026-01-01T00:00:00Z" },
    { role: "admin", userId: "u1" },
  );
  assert.ok(!self.includes(RLO), "the roster row carries no override either");
  assert.match(self, /class="set-row-name">mallory@evil\.com <span class="dim">\(you\)<\/span>/);

  // All TWELVE UAX#9 bidi formatting characters are neutralised, not just the
  // RLO: the nine explicit ones (LRE/RLE/LRO/RLO/PDF, LRI/RLI/FSI/PDI) and the
  // three implicit marks (LRM/RLM/ALM). The loop below is the count — it walks
  // the whole class, so a range narrowed in app.js reds here rather than
  // shrinking silently.
  for (const c of ["‎", "‏", "؜", "‪", "‫", "‬", "‭", "‮",
                   "⁦", "⁧", "⁨", "⁩"]) {
    assert.equal(hooks.esc("a" + c + "b"), "ab", "U+" + c.charCodeAt(0).toString(16) + " must not survive esc()");
  }
  // …and NOTHING ELSE MOVES: a string without them escapes byte-for-byte as
  // before, so no existing body.includes(...) assertion changes meaning.
  assert.equal(hooks.esc("<&\"'>"), "&lt;&amp;&quot;&#39;&gt;");
  assert.equal(hooks.esc("ops@acme.com created instance"), "ops@acme.com created instance");
  assert.equal(hooks.esc(null), "");
  // The strip runs BEFORE the escape, so an entity's letters can never be
  // re-read as text (the ssw8 esc-then-strip lesson, above).
  assert.equal(hooks.esc("a&" + RLO + "b"), "a&amp;b");
});

test("cch-w22-s5 (B): relTime — a future timestamp is never 'just now', and the past is byte-identical", () => {
  const now = Date.now();
  const at = (ms) => new Date(now + ms).toISOString();

  // THE DEFECT: Math.max(0, …) clamped every future delta to the freshest
  // possible answer, on the row that carries Revoke (sessionRowHtml :1105
  // beside .session-revoke :1110). Four futures, four distinct honest strings.
  const future = [at(30e3), at(24 * 3600e3), at(365 * 24 * 3600e3), "2999-01-01T00:00:00Z"].map((s) => hooks.relTime(s));
  assert.deepEqual(future.slice(0, 3), ["in <1m", "in 1d", "in 365d"]);
  assert.match(future[3], /^in \d+d$/);
  assert.equal(new Set(future).size, 4, "all four futures are distinguishable from each other");
  for (const s of future) assert.notEqual(s, "just now");

  // THE POSITIVE PATH IS UNCHANGED — these are exactly the strings main emits.
  assert.equal(hooks.relTime(at(-30e3)), "just now");
  assert.equal(hooks.relTime(at(-2 * 3600e3)), "2h ago");
  assert.equal(hooks.relTime(at(-5 * 24 * 3600e3)), "5d ago");
  assert.equal(hooks.relTime(at(-90e3)), "2m ago");
  assert.equal(hooks.relTime(null), "—");
  assert.equal(hooks.relTime("not-a-date"), "—");

  // …and the honest string reaches the screen beside the destructive control.
  const row = hooks.sessionRowHtml({ id: "s1", user_agent: "barkpark-cli/0.9", last_used_at: at(24 * 3600e3) });
  assert.ok(row.includes("Active in 1d"), "the session row states the skew instead of claiming freshness");
  assert.ok(row.includes("session-revoke"), "…on the same row as Revoke");
});

// ── cch-w25-s2: the theater's min-content escape, and the ONE declaration that
//    silently un-fixes it ─────────────────────────────────────────────────────
// The defect is geometry and its real proof is the browser leg
// (W24-theater-failed-hostname-whole, now driving theater-failed AND
// theater-midflight, page + every theater box asserted). What a node run CAN own
// is the source-level shape that leg is slow to report: a `margin-left` where a
// `padding-left` belongs. That swap PASSES every page-level assertion in this
// repo while opening a silent 34px internal overflow (.new-step 210/176,
// measured by driving it), because the global border-box reset contains padding
// and never margin. It is a one-word tidy-up a future author will find inviting,
// and this test is what makes the swap cost four seconds instead of a browser run.
// Appended at the END on the file's own rule: node --test numbers positionally.
test("cch-w25-s2: the <=720 theater block escapes min-content AND pays the step-row budget with PADDING", () => {
  const css = fs.readFileSync(new URL("./app.css", import.meta.url), "utf8");
  // Anchored on the declaration that stacks the theater, never on ordinal —
  // app.css carries several 720 blocks.
  const anchor = css.indexOf(".new-theater-grid { grid-template-columns:");
  assert.ok(anchor > 0, "the theater/phone block must still carry the stacked track");
  const at = css.lastIndexOf("@media (max-width: 720px)", anchor);
  assert.ok(at > 0, "the stacked track must live inside a 720px block");
  const block = css.slice(at, css.indexOf("\n}\n", anchor) + 3);
  // The escape. A bare `1fr` is `minmax(auto, 1fr)` — its floor is min-content,
  // which is exactly how the track measured 251/214 inside its own card at 320
  // with the ORDINARY hostname, no cruel string involved.
  assert.match(block, /\.new-theater-grid \{ grid-template-columns: minmax\(0, 1fr\);/,
    "a bare 1fr floors at min-content and the theater track overflows its card at 320");
  // The escape ALONE puts the hostname tear back (.new-step-body returns to a
  // 92.25px box). These two are the other half and may never ship without it.
  assert.match(block, /\.new-step \{ flex-wrap: wrap; \}/,
    "without wrapping the row, the nowrap time column keeps 34px of a 176px row and the hostname tears");
  assert.match(block, /\.new-step-time \{ margin-left: 0; flex: 1 0 100%; padding-left: 34px; \}/,
    "the reflowed time must clear the auto margin, take its own line, and be inset with PADDING");
  // The trap, stated as its own assertion so the failure message IS the reason.
  // Read the VALUE and compare it — a negative lookahead here would backtrack
  // over its own `\s*` and pass on any value at all, which is a guard that
  // cannot lose wearing the costume of one.
  const timeRule = block.slice(block.indexOf(".new-step-time {")).split("}")[0];
  assert.equal((timeRule.match(/margin-left:\s*([^;]+)/) || [])[1], "0",
    "margin-left on the reflowed time passes every page-level guard and opens a silent 34px .new-step overflow — use padding-left");
  assert.ok(/padding-left:\s*34px/.test(timeRule),
    "the 34px inset (dot 22 + row gap 12) is what keeps the time under its own label");
  // And the browser leg that owns the geometry must still drive BOTH theater
  // screens. Mid-flight is the screen every successful signup watches and had
  // zero coverage in that file until this row; a remedy that quietly reshapes it
  // is the blind spot, not a bonus.
  const guard = fs.readFileSync(new URL("./__preview__/overflow-guard.mjs", import.meta.url), "utf8");
  assert.match(guard, /SCENARIOS\["theater-midflight"\]/,
    "the guard leg must drive theater-midflight — it shares every rule this remedy touched");
  assert.ok(!/RESIDUAL \(reported, not asserted/.test(guard),
    "the cruel-host page number is 320/320 now and is ASSERTED; the reported-not-asserted block must be gone");
});

// ── cch-w17-bl-overflow-guard-honours-one-defect-flag ────────────────────────
//
// `overflow-guard.mjs` resolved its leg selection with
// `argv.indexOf("--defect")`, and indexOf returns the FIRST match. So
// `--defect A --defect B` measured A, dropped B WITHOUT A WORD, and printed
// `OVERFLOW GUARD PASS` at exit 0 — a green covering one of the two legs the
// caller asked for, with nothing in the output saying so. Measured live on
// origin/main at 4d223c151a: `W13-detail-route-band — … (108 cells)` printed,
// `W15-fleet-row-text-bounded` absent from the run entirely, exit 0.
//
// WHY THE ASSERTION LIVES HERE and not only beside the module it tests: this
// file is the `console-unit` step of the REQUIRED `Console gate`, and the
// parser's own suite (__preview__/defect-selection.test.mjs, 13 cases) is not
// enumerated in console-harness.yml — `.github/` was outside the fixing row's
// edit scope, and that workflow names each `node --test` file by hand. A test
// nothing runs is the class of code this epic exists to empty, so the
// load-bearing case is mirrored here, where it is live on the merge path today.
// Wiring the full suite is one `- run:` line beside the other four
// `__preview__` suites in the `console-unit` job.
test("cch-w17-bl: overflow-guard honours EVERY --defect flag — a repeated flag is not silently dropped", async () => {
  const { selectDefects } = await import("./__preview__/defect-selection.mjs");
  const known = ["alpha-leg", "beta-leg", "gamma-leg"];

  const two = selectDefects(["--defect", "alpha-leg", "--defect", "gamma-leg"], known);
  assert.equal(two.refusal, undefined,
    "a repeated --defect is a well-formed request, not an environment fault: this guard's exit 2 " +
    "makes NO claim about the CSS and must not be spent on an invocation it can read");
  assert.deepEqual(two.requested, ["alpha-leg", "gamma-leg"],
    "the SECOND --defect must be measured too — dropping it produces a PASS covering one of the " +
    "two legs the operator asked for, which is this guard's own failure mode turned inward");

  // The callers that exist today, unmoved: console-harness.yml passes no flag at
  // all, seal-predicate.mjs spawns exactly one.
  assert.deepEqual(selectDefects([], known).requested, known,
    "no flag still means every defect — the only invocation the required gate makes");
  assert.deepEqual(selectDefects(["--defect", "beta-leg"], known).requested, ["beta-leg"],
    "one flag still means one leg — seal-predicate.mjs's spawn shape");

  // THE REFUSAL THIS GUARD ALREADY HAD, byte for byte. seal-predicate.mjs's
  // doctrine block cites this sentence by name; a reader of the guard's log must
  // see no change in it.
  assert.equal(
    selectDefects(["--defect", "delta-leg"], known).refusal,
    `!! GUARD (exit 2): unknown --defect "delta-leg". Known: alpha-leg, beta-leg, gamma-leg\n`);

  // …and the guard must actually ROUTE through the parser. A fixed parser
  // nothing calls is not a fix. Line comments are stripped first because the
  // guard's new comment QUOTES the deleted expression on purpose — that is the
  // search vocabulary for this row and it has to survive.
  const guard = fs.readFileSync(new URL("./__preview__/overflow-guard.mjs", import.meta.url), "utf8");
  const code = guard.split("\n").filter((l) => !/^\s*\/\//.test(l)).join("\n");
  assert.ok(!/argv\.indexOf\("--defect"\)/.test(code),
    "indexOf returns the FIRST match — that expression IS the defect this row closed");
  assert.match(code, /const selection = selectDefects\(argv, DEFECTS\);/,
    "the guard must resolve its legs through the parser these assertions drive");
  assert.match(code, /if \(selection\.refusal\) \{\s*\n\s*process\.stderr\.write\(selection\.refusal\);\s*\n\s*process\.exit\(2\);/,
    "a malformed selection stays a REFUSAL at exit 2 — downgrading it to a warning would trade " +
    "a loud usage error for a silent partial measurement, the same defect one level down");
});

// ── cch-w28-bl-overflow-guard-clipper-blames-the-wrong-panel ─────────────────
//
// The two clipper legs (W26-deploy-fail-clip, W27-deploy-ref-branch-bounded)
// used to fire on the ANCESTOR CARD's overflow while their sentence named the
// PANEL. Re-derived in a browser by deleting `.deploy-ref { overflow-wrap:
// anywhere }`: 16 findings across 20 cells saying "388px of a failed deploy's
// reason is inside a box that clips it" while every `.deploy-fail` under that
// clipper stopped 106-506px SHORT of the clip edge.
//
// A BROWSER CANNOT GUARD THIS ONE. The false report only appears while some
// SIBLING regression is live, so a green tree renders nothing to assert against
// — there is no pixel that reds when the wording rots back. What is durable is
// the SHAPE of the two legs, which is why this is a source read and not a
// render: the dedupe key must be element identity, the grouping must be element
// identity, and the un-attributed arm must exist in both legs.
test("cch-w28-bl: both clipper legs key on the ELEMENT and refuse to attribute an unattributable overflow", () => {
  const guard = fs.readFileSync(new URL("./__preview__/overflow-guard.mjs", import.meta.url), "utf8");

  // (b) THE DEDUPE KEY. `clippersSaid` used to hold a 40-char class PREFIX, so
  // two different clipping ancestors agreeing in their first 40 chars collapsed
  // into one entry and the second real clipper was silenced. Proven live under a
  // 41-char shared prefix: 16 findings with the prefix key, 26 with element
  // identity, and only one of the two clippers named per cell.
  assert.equal((guard.match(/clippersSaid\.add\(b\.ci\)/g) || []).length, 2,
    "both clipper legs must key their one-voice-per-clipper Set on the clipping ELEMENT (b.ci)");
  assert.equal((guard.match(/clippersSaid\.(add|has)\(b\.cl\)/g) || []).length, 0,
    "no leg may key the clipper Set on b.cl — that is a class STRING, and it was truncated to 40 chars");
  assert.match(guard, /rec\.ci=ci;/,
    "the in-page collector must stamp a per-element clipper id");
  assert.ok(!/rec\.cl=\(cl\.className\|\|cl\.tagName\|\|'\?'\)\.toString\(\)\.slice\(0,40\)/.test(guard),
    "the clipper class must be carried UNTRUNCATED — it is display text now, never a key");

  // (a) + (c) THE GROUPING AND THE SENTENCE. The panels under a clipper must be
  // gathered by element identity too (the same collision, one line down), and
  // an overflow no panel accounts for must say so rather than name an innocent
  // one as its filler.
  assert.equal((guard.match(/\.filter\(\(x\) => x\.ci === b\.ci\)/g) || []).length, 2,
    "both legs must gather the panels under a clipper by element identity");
  assert.equal((guard.match(/\.filter\(\(x\) => x\.cl === b\.cl\)/g) || []).length, 0,
    "no leg may gather panels by a truncated class string");
  assert.equal((guard.match(/UN-ATTRIBUTED: not one of the/g) || []).length, 2,
    "both legs must carry the un-attributed arm — a clipper that overflows while nothing under it loses a glyph");
  // ANCHORED ON THE EMITTED STRING, NOT THE PHRASE. A bare phrase match reds on
  // the comment that EXPLAINS the old label — the fix's own prose would fail its
  // own guard. `${` after the colon is what makes this an interpolated fail()
  // argument rather than a sentence about one.
  assert.equal((guard.match(/widest (panel|ref) inside it: \$\{/g) || []).length, 0,
    "the old label is gone: the winner was selected by glyph proximity and then announced as the WIDEST, which it need not be");
  // The filler is now chosen among SPILLERS only, by the same quantity it is
  // described with. The `?? -1e9` guard is what made a null `lost` sort like a
  // value; with spillers pre-filtered, `lost` is a number by construction.
  assert.equal((guard.match(/\(y\.lost \?\? -1e9\) - \(x\.lost \?\? -1e9\)/g) || []).length, 0,
    "no clipper filler may be sorted with a null-coalescing key — filter to spillers first");
  assert.equal((guard.match(/spillers\.slice\(\)\.sort\(\(x, y\) => y\.lost - x\.lost\)\[0\]/g) || []).length, 2,
    "both legs must pick the filler from the spillers, ranked by pixels actually lost");
});

// ── cch-w28-s8: A NEVER-DEPLOYED SITE ROW SAYS SO ────────────────────────────
//
// siteRow's badge strip was siteOpenLink + siteBindingChip + freshnessBadge.
// freshnessBadge opens `var m = freshnessModel(s); if (!m) return "";`, and
// cch-w16-s4 correctly withholds the Visit door from a site that never served a
// build — so the never-deployed row rendered TWO fewer controls than its
// neighbours and never said why. Both directions are asserted: the never-
// deployed row gains the neutral indicator, the deployed row keeps its badge.
// Appended at the END on the file's own rule: node --test numbers positionally.
test("cch-w28-s8: a never-deployed site row states 'Not deployed'; a deployed row is untouched", () => {
  // THE FIXTURE MUST BE ABLE TO PRODUCE THE DEFECT (standing-test clause 4):
  // no `last_deployment` and no `current_deployment_id`, so freshnessModel is
  // genuinely nil and the old strip genuinely rendered "".
  const never = {
    id: "site-nd", slug: "acme-app", name: "acme-app", framework: "nextjs",
    domains: ["app.acme.com"], github_repo: "acme/app", github_branch: "main",
    github_webhook_configured: true,
  };
  assert.ok(!("last_deployment" in never) && !("current_deployment_id" in never),
    "the fixture must carry NO deploy fact — otherwise this test is green by construction");
  assert.ok(!hooks.freshnessModel(never),
    "freshnessModel must really be nil for this fixture — that nil IS the defect's cause");
  assert.equal(hooks.freshnessBadge(never), "",
    "and the badge it feeds really renders nothing");

  const BP = { id: "bp-1", name: "Production", url: "https://acme.barkpark.cloud" };
  const row = hooks.siteRow(never, BP);
  // The visible copy is the word D182 already ruled and the global list already
  // paints — not a new sentence invented for this row.
  assert.ok(row.includes(">Not deployed</span>"),
    "the never-deployed row must SAY it is not deployed, not fall silent");
  assert.ok(hooks.siteStatusPill(never).includes(">Not deployed<"),
    "the row's word is the global sites list's word — one vocabulary, not two");
  assert.match(row, /title="Not deployed to production"/,
    "the tooltip names the environment, as the site-detail head already does");
  assert.match(row, /aria-label="Not deployed to production"/,
    "…and so does the accessible name — a screen reader must not guess at branch previews");
  // NIL-HONEST: no invented green, no invented door, no fabricated timestamp.
  assert.ok(!row.includes("site-open") && !row.includes("Visit"),
    "cch-w16-s4's gate still holds — no door to a site that never served a build");
  assert.ok(!/fresh-badge--(up|down|deploy|rebuild)/.test(row),
    "the indicator must be the NEUTRAL base badge, never a coloured state it has not earned");
  assert.ok(!row.includes("fresh-meta"),
    "there is no deploy, so there is no timestamp — none may be fabricated");
  // NO NEW CSS CLASS: app.css is drift-gated and this wave seated no cssom
  // holder, so every class the new segment emits must already have a rule.
  const s8css = fs.readFileSync(new URL("./app.css", import.meta.url), "utf8");
  for (const cls of ["fresh-badge", "fresh-dot", "fresh-label"]) {
    assert.ok(s8css.includes("." + cls + " "), "the row reuses the existing ." + cls + " rule");
  }

  // ARM 2 — THE DEPLOYED ROW IS UNCHANGED. Same site, one deploy fact added:
  // it keeps its freshness badge verbatim and gains NO extra indicator.
  const deployed = Object.assign({}, never, {
    current_deployment_id: "dep-1",
    last_deployment: {
      status: "live", trigger: "manual", updated_at: new Date().toISOString(),
    },
  });
  const liveRow = hooks.siteRow(deployed, BP);
  assert.ok(liveRow.includes("fresh-badge--up") && liveRow.includes(">Live<"),
    "a deployed row still states its freshness");
  assert.ok(!liveRow.includes("Not deployed"),
    "…and never carries the never-deployed sentence beside a live badge");
  // Byte-level: the deployed row's badge slot IS freshnessBadge's own output,
  // so this slice added nothing to the path it did not own.
  assert.ok(liveRow.includes(hooks.freshnessBadge(deployed)),
    "the deployed row's freshness badge is freshnessBadge's output, unmodified");
});

// ── cch-w30-s5: a control-plane CRASH must not render as the person's mistake ──
//
// The wire bytes are only half the fix. api() hands a crash to callers as
// {ok:false, status:5xx, data:<envelope>} and friendly()'s precedence is
// curated ERRORS → details → THE CALLER'S FALLBACK → humanized slug. So a
// server-fault slug that is not registered in ERRORS loses to a fallback
// written for a validation failure, and the person still reads "Check the
// details and try again." about a fault that was never theirs. These tests
// drive the REAL friendly()/faultCopy() with the REAL envelope the router now
// sends and pin the RENDERED SENTENCE.

test("cch-w30-s5: every crash slug the router can send is registered in ERRORS", () => {
  // CENSUS, not a hand list: side A is parsed out of the router's own
  // crash_slug/2 clauses, so adding a slug there without adding copy here reds.
  const router = fs.readFileSync(
    new URL("../../lib/barkpark_cloud/web/router.ex", import.meta.url), "utf8");
  const slugs = [...router.matchAll(/defp crash_slug\([\s\S]*?do:\s*"([a-z_]+)"/g)]
    .map((m) => m[1]);
  assert.ok(slugs.length >= 5, "the router declares crash slugs (found " + slugs.length + ")");
  for (const slug of slugs) {
    const copy = hooks.friendly({ error: slug }, "Check the details and try again.");
    assert.notEqual(copy, "Check the details and try again.",
      slug + " is unregistered in ERRORS, so it loses to the blaming fallback");
    assert.notEqual(copy, slug.replace(/_/g, " "),
      slug + " renders as a humanized slug, not curated copy");
    assert.ok(!/check the (details|form|values|address)/i.test(copy),
      slug + " must not tell the person to re-check input they got right");
  }
});

test("cch-w30-s5: the router's own 500 envelope renders server-fault copy", () => {
  // Byte-for-byte the shape handle_errors/2 sends: FLAT error + request_id.
  const envelope = { error: "server_error", request_id: "0a1b2c3d4e5f6071" };
  assert.match(hooks.friendly(envelope, "Check the form and try again."),
    /broke on our side/i);
  // cch-w62 (D740) — THIS PIN IS INVERTED. It used to assert the nested
  // api/-style shape fell back to the blaming copy, "because the envelope must
  // stay flat" (router.ex:8627-8630's premise). That premise is false by 31
  // nested emitters in the same router file — five route families (self-update,
  // rollback, the webhook proxy, PATCH /autoupdate, PATCH /admin channel) send
  // {error:{code}} today. friendly() now unwraps the object and resolves the
  // slug through the normal ladder, so a nested server_error renders the
  // server-fault sentence instead of blaming input nobody judged.
  const nested = { error: { code: "server_error" } };
  assert.match(hooks.friendly(nested, "Check the form and try again."),
    /broke on our side/i);
});

test("cch-w30-s5: faultCopy swaps the validation fallback out on a 5xx only", () => {
  const fb = "Check the details and try again.";
  // 5xx WITH the envelope → curated server copy.
  assert.match(hooks.faultCopy(500, { error: "server_error" }, fb), /broke on our side/i);
  // 5xx with NO parseable body at all (an upstream proxy's HTML page): still
  // never blames the input.
  assert.match(hooks.faultCopy(502, {}, fb), /broke on our side/i);
  assert.ok(!/check the details/i.test(hooks.faultCopy(502, {}, fb)));
  // 4xx is a real answer ABOUT the input — the caller's designed copy survives.
  assert.equal(hooks.faultCopy(422, {}, fb), fb);
  assert.equal(hooks.faultCopy(409, { error: "unknown_slug" }, fb), fb);
  // A genuine transport failure keeps connection-specific copy (api() returns
  // status 0 with the network_error slug).
  assert.match(hooks.faultCopy(0, { error: "network_error" }, "Check your connection and retry."),
    /Network error/i);
  // 413 is a real answer about what was sent, and it names the true cause.
  assert.match(hooks.faultCopy(413, { error: "request_too_large" }, fb), /too large/i);
});

test("cch-w30-s5: the named copy helper stops blaming the person on a 5xx", () => {
  // The env-var write twin was deleted with the feature (cch-w53-bl, Option A);
  // inviteFailureCopy is the surviving helper of the pair this slice fixed.
  // invite: "Check the address and try again." was a lie on a 500.
  assert.match(hooks.inviteFailureCopy({ error: "server_error" }, 500), /broke on our side/i);
  assert.ok(!/check the address/i.test(hooks.inviteFailureCopy({}, 500)));
  // …and the 4xx answers it was written for are untouched.
  assert.match(hooks.inviteFailureCopy({ error: "already_member" }, 409), /already on your team/i);
  assert.match(hooks.inviteFailureCopy({}, 422), /Check the address/i);
});

test("cch-w30-s5: no crash-path caller re-blames the input behind faultCopy's back", () => {
  // The six fallbacks the survey caught. Each MUST now be routed through
  // faultCopy — a future edit that reverts one to a bare friendly() reds here.
  const src = fs.readFileSync(new URL("./app.js", import.meta.url), "utf8");
  for (const fallback of [
    "Check the details and try again.",
    "Check the form and try again.",
    "Check the address and try again.",
    // cch-w31-s4 — the two sentences the survey found STILL bare. Each one is
    // added in the same change as its fix, and each REDS this test on its own:
    // the connection sentence sat at the fleet + billing degradation cards with
    // the status thrown away one frame up, and the details sentence was
    // webhookMutationError's terminal fall-through, which a flat crash envelope
    // reached every single time.
    "Check your connection and retry.",
    "Please check the details and try again.",
  ]) {
    const idx = [...src.matchAll(new RegExp(fallback.replace(/\./g, "\\."), "g"))].map((m) => m.index);
    assert.ok(idx.length > 0, "fallback still present: " + fallback);
    for (const i of idx) {
      const line = src.slice(src.lastIndexOf("\n", i) + 1, src.indexOf("\n", i));
      if (!line.trimStart().startsWith("//")) {
        assert.ok(line.includes("faultCopy("),
          "a blaming fallback is reachable without the 5xx switch: " + line.trim());
      }
    }
  }
  // The instance-timeline site blamed the USER'S NETWORK for a server 500.
  assert.match(src, /faultCopy\(ev\.status, ev\.data, "Check your connection and retry\."\)/);
});

// ── cch-w31-s4: a control-plane 500 must not tell the person to check THEIR details ──
//
// cch-w30-s5 fixed the named copy helpers. The three sentences below were the
// ones still standing, and every one of them failed for the SAME structural
// reason: the response status existed exactly one frame above the sentence and
// was thrown away before any copy could be chosen. So these tests drive the
// real helpers with the real crash envelopes, and pin the seams that carry the
// status down — not just the sentences.

test("cch-w31-s4: webhookMutationError never blames the person for a control-plane crash", () => {
  // The four shapes a crash actually arrives as. Before this slice EVERY one of
  // them returned "Please check the details and try again." — the flat envelope
  // has no err.code and no err.detail, so every branch fell through.
  const cases = [
    ["router 500", 500, { error: "server_error" }],
    ["500 + request_id", 500, { error: "server_error", request_id: "0a1b2c3d4e5f6071" }],
    ["empty body (HTML 502)", 502, {}],
    ["bad_gateway", 502, { error: "bad_gateway" }],
  ];
  for (const [label, status, data] of cases) {
    const copy = hooks.webhookMutationError(data, status);
    assert.ok(!/check the details/i.test(copy),
      label + " still tells the person to check their details: " + copy);
    assert.match(copy, /broke on our side/i, label + " must name US as the party at fault");
  }
  // A transport failure is not the person's input either — and it is not a 5xx,
  // so it must come out of the status-0 arm, not the server-fault arm.
  assert.match(hooks.webhookMutationError({ error: "network_error" }, 0), /[Nn]etwork error/);
  assert.ok(!/check the details/i.test(hooks.webhookMutationError({}, 0)));
});

test("cch-w31-s4: webhookMutationError's specific branches still win over the status switch", () => {
  // The status is consulted ONLY at the terminal fall-through. A proxied 502
  // that carries a real instance validation error must still read as that field
  // error — swallowing it into generic crash copy would be a different lie.
  assert.equal(
    hooks.webhookMutationError({ error: { code: "upstream_error", status: 422, detail: { error: { details: { url: ["must be https"] } } } } }, 502),
    "url must be https");
  assert.equal(hooks.webhookMutationError({ ok: false, error: { code: "instance_unreachable" }, reachable: false }, 502),
    "Couldn't reach the instance — the change is unconfirmed.");
  assert.match(hooks.webhookMutationError({ error: { code: "capability_unavailable" } }, 501), /needs an update/i);
  // A REAL 4xx answer about the input keeps the copy that was written for it.
  assert.equal(hooks.webhookMutationError({}, 422), "Please check the details and try again.");
  // No status at all (an un-migrated caller) degrades to exactly the old
  // behaviour rather than inventing a fault class.
  assert.equal(hooks.webhookMutationError({}), "Please check the details and try again.");
});

test("cch-w31-s4: every webhookMutationError call site passes the status it already had", () => {
  const src = fs.readFileSync(new URL("./app.js", import.meta.url), "utf8");
  const calls = [...src.matchAll(/webhookMutationError\(([^)]*)\)/g)]
    .map((m) => m[1].trim())
    .filter((a) => a !== "data, status"); // the declaration itself
  assert.equal(calls.length, 7, "the seven mutation call sites (found " + calls.length + ")");
  for (const args of calls) {
    assert.equal(args, "r.data, r.status", "a call site still discards the status: " + args);
  }
});

test("cch-w31-s4: faultCopy has a status-0 arm, capped at THREE honest transport classes", () => {
  const fb = "Check your connection and retry.";
  // status 0 = the request never got an answer, so a fallback written about the
  // INPUT is as much a lie as it is on a 5xx.
  assert.match(hooks.faultCopy(0, {}, fb), /[Nn]etwork error/);
  assert.ok(!/check your connection and retry/i.test(hooks.faultCopy(0, {}, fb)));
  // THE ENVELOPE api() ACTUALLY PRODUCES, not a convenient one. Every transport
  // failure arrives as `{ error: "network_error" }` — never `{}` — and
  // friendly() resolves that slug out of ERRORS before it reads any fallback.
  // Asserting the transport classes against `{}` was vacuous: it proved a shape
  // this console never emits, while the shape it does emit collapsed all three
  // classes to one generic sentence. (Review fix, wave 31.)
  const wire = { error: "network_error" };
  assert.match(hooks.faultCopy(0, wire, fb, "offline"), /offline/i);
  assert.match(hooks.faultCopy(0, wire, fb, "aborted"), /cancelled/i);
  assert.match(hooks.faultCopy(0, wire, fb, "unreachable"), /[Nn]etwork error/);
  assert.ok(!/check your connection and retry/i.test(hooks.faultCopy(0, wire, fb, "offline")));
  // …and the classes must be DISTINGUISHABLE on that envelope, or the
  // vocabulary is decoration: three classes, three sentences.
  assert.equal(
    new Set(["offline", "aborted", "unreachable"].map((t) => hooks.faultCopy(0, wire, fb, t))).size,
    3,
    "the transport classes collapse to one sentence on api()'s real envelope",
  );
  assert.match(hooks.faultCopy(0, {}, fb, "offline"), /offline/i);
  assert.match(hooks.faultCopy(0, {}, fb, "aborted"), /cancelled/i);
  assert.match(hooks.faultCopy(0, {}, fb, "unreachable"), /[Nn]etwork error/);
  // The status-0 arm must not disturb the arms cch-w30-s5 pinned.
  assert.match(hooks.faultCopy(500, { error: "server_error" }, fb), /broke on our side/i);
  assert.equal(hooks.faultCopy(422, {}, "Check the values and try again."), "Check the values and try again.");
});

test("cch-w31-s4: the transport vocabulary REFUSES a DNS-vs-network promise", () => {
  // Three classes, and no fourth. A browser collapses DNS failure, refused,
  // TLS and offline into one indistinguishable TypeError, so a fourth class
  // would be this console inventing a fact it cannot have — the exact failure
  // mode the wave exists to stop. If someone adds one, this reds.
  assert.equal(hooks.transportClass({ name: "AbortError" }), "aborted");
  assert.equal(hooks.transportClass(new TypeError("Failed to fetch")), "unreachable");
  assert.equal(hooks.transportClass(undefined), "unreachable");
  const classes = new Set([
    hooks.transportClass({ name: "AbortError" }),
    hooks.transportClass(new TypeError("Failed to fetch")),
    hooks.transportClass({ name: "TypeError", message: "NetworkError when attempting to fetch resource." }),
    hooks.transportClass({ message: "getaddrinfo ENOTFOUND api.example" }),
  ]);
  assert.deepEqual([...classes].sort(), ["aborted", "unreachable"],
    "a DNS-shaped message must NOT earn its own class");
  // Copy is total: an unknown class degrades to the sentence that is always
  // true at status 0 rather than to silence.
  assert.match(hooks.transportCopy("who_knows"), /[Nn]etwork error/);
  assert.match(hooks.transportCopy(undefined), /[Nn]etwork error/);
  // …and the refusal is stated in the source, not just in a commit message.
  const src = fs.readFileSync(new URL("./app.js", import.meta.url), "utf8");
  assert.match(src, /indistinguishable TypeError/);
});

test("cch-w31-s4: api()'s envelope is ADDITIVE — status 0 and network_error survive verbatim", () => {
  const src = fs.readFileSync(new URL("./app.js", import.meta.url), "utf8");
  // The transport-failure sentinel every consumer branches on, byte-for-byte.
  assert.match(src, /\{ ok: false, status: 0, data: \{ error: "network_error" \}/);
  // The four hand-rolled status === 0 branches and both live network_error
  // string branches are still there — the envelope added fields, it repurposed
  // nothing. (Five code branches now: the four originals plus faultCopy's own
  // arm, which is what lets the four retire at the seam later.)
  // cch-w36-s4 raises the pin to SIX: operatorReadFault classifies a status-0
  // operator read as `unreachable` so a card that never got an answer stops
  // reading like one that got a refusal. The pin is a set-size ratchet on
  // ADDITIONS, not a ban on them — a branch that DISAPPEARS still reds it.
  // cch-w53-bl (env-var Option A, 2026-09-02) takes the pin 6 -> 5: one of the
  // four originals was envVarsFailureCopy's, deleted with the team env-var
  // feature. A branch that DISAPPEARS reds this — which is what it just did.
  // cch-w36-bl (console-3-w26) takes it 5 -> 7: metricsFailureCopy and
  // usageFailureCopy each GREW one. Both routes are total over a sick box, so
  // their old status-blind default told a person whose network died that the
  // instance "may be starting up"; a status-0 arm is the branch that stops it.
  // The pin stays a ratchet on ADDITIONS — a branch that disappears still reds.
  const zeroBranches = [...src.matchAll(/^\s*if \(status === 0\)/gm)];
  assert.equal(zeroBranches.length, 7,
    "the three surviving original status-0 branches, faultCopy's arm, operatorReadFault's, " +
    "and the metrics/usage arms (found " + zeroBranches.length + ")");
  assert.ok([...src.matchAll(/err === "network_error"/g)].length >= 2);
  // A non-JSON body still hands consumers an EMPTY data object (all 354 .data
  // reads unchanged) — the bytes now ride alongside as `text` instead of
  // vanishing, which is the whole of the addition.
  assert.match(src, /return \{ data: \{\}, text: t \};/);
  assert.match(src, /return \{ ok: res\.ok, status: res\.status, data: body\.data, text: body\.text, transport: null \};/);
});

test("cch-w31-s4: the fleet and subscription caches RETAIN the fault they used to discard", () => {
  const src = fs.readFileSync(new URL("./app.js", import.meta.url), "utf8");
  // ensureFleet(): the list-or-null collapse now writes the fault beside it…
  const ensure = src.slice(src.indexOf("function ensureFleet()"));
  const ensureBody = ensure.slice(0, ensure.indexOf("\n  }"));
  // (the follow-up slice added `text` — the captured non-JSON body — to the
  // retained fault so the instance-load card can show what the server said.)
  assert.match(ensureBody, /fleetFault = \{ status: r\.status, data: r\.data, text: r\.text, transport: r\.transport \}/);
  assert.match(ensureBody, /fleetFault = null/, "a success must clear the retained fault");
  // …and loadSubscription()'s bare boolean gained the same companion.
  const load = src.slice(src.indexOf("function loadSubscription()"));
  const loadBody = load.slice(0, load.indexOf("\n  }"));
  assert.match(loadBody, /subErrorFault = \{ status: r\.status, data: r\.data, transport: r\.transport \}/);
  assert.match(loadBody, /subErrorFault = null/, "a success must clear the retained fault");
  // The flag and its fault are reset in lockstep EVERYWHERE — a stale fault
  // outliving its flag would put last hour's 500 on this minute's retry card.
  assert.equal([...src.matchAll(/subError = false/g)].length,
    [...src.matchAll(/subErrorFault = null/g)].length,
    "every subError reset must clear subErrorFault too");
});

// ── cch-w31-s4 follow-up: THE CAPTURED 5xx BODY GETS A READER ──────────────
// The group above pins api()'s envelope by READING app.js as text, and that pin
// has real but narrow power: deleting the field (`text: body.text` -> `text:
// null`) reds it. What it structurally cannot see is the arm being turned OFF —
// `} else if (false && typeof res.text === "function") {` leaves every pinned
// line byte-identical, kills body recovery completely, and the whole harness
// stays green. So api() is exported now and DRIVEN: a real call against a 502
// text/html stub that has NO json method at all (the JSON arm is unreachable by
// construction, not by convention) must come back carrying the proxy's bytes,
// and those bytes must reach a surface a person can read.

// A stub shaped like an upstream proxy that never spoke JSON: real
// headers.get() switch, a text() body, and DELIBERATELY no json method.
function proxyFaultFetch(status, contentType, bodyText) {
  const calls = [];
  const fn = (path, opts) => {
    calls.push({ path, opts });
    return Promise.resolve({
      ok: status >= 200 && status < 300,
      status,
      headers: { get: (n) => (String(n).toLowerCase() === "content-type" ? contentType : null) },
      text: () => Promise.resolve(bodyText),
    });
  };
  fn.calls = calls;
  return fn;
}

// Swap the one global api() reads, drive it to completion, restore.
async function driveApi(fetchFn, method, path) {
  const saved = sandbox.fetch;
  sandbox.fetch = fetchFn;
  try {
    return await hooks.api(method || "GET", path || "/v1/barkparks");
  } finally {
    sandbox.fetch = saved;
  }
}

const NGINX_502 =
  "<html>\r\n<head><title>502 Bad Gateway</title></head>\r\n<body>\n" +
  "<center><h1>502 Bad Gateway</h1></center>\n<hr><center>nginx/1.24.0</center>\n" +
  "</body>\r\n</html>\r\n";

test("cch-w31-s4 follow-up: api() is exported, so the envelope is drivable at all", () => {
  assert.equal(typeof hooks.api, "function",
    "api must be in __bpTestHook — without it no behavioural fixture is possible");
});

test("cch-w31-s4 follow-up: a 502 text/html answer arrives with the proxy's bytes as .text", async () => {
  const r = await driveApi(proxyFaultFetch(502, "text/html", NGINX_502));
  assert.equal(r.ok, false);
  assert.equal(r.status, 502);
  // `data` is untouched by the addition — still the empty object every .data
  // read already expects. (Cross-realm object: compare by shape, not identity.)
  assert.equal(typeof r.data, "object");
  assert.equal(Object.keys(r.data).length, 0);
  assert.equal(r.transport, null, "an answered request is not a transport failure");
  // THE POINT: the bytes survived instead of vanishing into {}.
  assert.equal(typeof r.text, "string");
  assert.match(r.text, /502 Bad Gateway/);
  assert.match(r.text, /nginx/);
});

test("cch-w31-s4 follow-up: a JSON answer still yields text === null", async () => {
  const jsonish = (path, opts) => {
    void path; void opts;
    return Promise.resolve({
      ok: false, status: 500,
      headers: { get: () => "application/json; charset=utf-8" },
      json: () => Promise.resolve({ error: "server_error" }),
    });
  };
  const r = await driveApi(jsonish);
  assert.equal(r.text, null, "the recovery arm must not fire on a parseable body");
  assert.equal(r.data.error, "server_error");
});

test("cch-w31-s4 follow-up: faultDetail turns an HTML error page into readable, bounded prose", () => {
  const detail = hooks.faultDetail(NGINX_502);
  assert.match(detail, /502 Bad Gateway/);
  assert.match(detail, /nginx/);
  assert.ok(detail.indexOf("<") === -1 && detail.indexOf(">") === -1,
    "markup must be stripped, never handed onward as markup");
  assert.ok(detail.length <= 161, "the excerpt is bounded (found " + detail.length + ")");
  // Total over junk — and "" is the signal the seam uses to render NOTHING,
  // so an empty detail line never promises a detail it does not have.
  assert.equal(hooks.faultDetail(null), "");
  assert.equal(hooks.faultDetail(undefined), "");
  assert.equal(hooks.faultDetail(""), "");
  assert.equal(hooks.faultDetail("<html><body>   </body></html>"), "");
  // A long body is cut on a word boundary with an ellipsis, not mid-word.
  const long = hooks.faultDetail("word ".repeat(200));
  assert.ok(long.length <= 161 && long.endsWith("…"));
});

test("cch-w31-s4 follow-up: THE BYTES REACH A SURFACE — the instance-load card renders them", async () => {
  const r = await driveApi(proxyFaultFetch(502, "text/html", NGINX_502));
  // Exactly what ensureFleet() now retains, built from a REAL api() answer.
  const html = hooks.fleetLoadErrorHtml({ status: r.status, data: r.data, text: r.text, transport: r.transport });
  // The honest 5xx sentence is unchanged…
  assert.match(html, /broke on our side/);
  // …and the body the person could not see before is now on the card.
  assert.match(html, /The server replied/);
  assert.match(html, /502 Bad Gateway/);
  assert.match(html, /nginx/);
  // Escaped, not injected: no tag from the upstream page survives as markup.
  assert.ok(html.indexOf("<html") === -1 && html.indexOf("<center") === -1,
    "the upstream page must be escaped into text, never mounted as markup");
  assert.match(html, /id="inst-load-retry"/, "the retry affordance stays");
});

test("cch-w31-s4 follow-up: with no recovered body the card gains NOTHING — no empty detail line", () => {
  const plain = hooks.fleetLoadErrorHtml({ status: 500, data: { error: "server_error" }, text: null, transport: null });
  assert.match(plain, /broke on our side/);
  assert.ok(plain.indexOf("The server replied") === -1);
  // Transport failures keep the class copy the two existing consumers rely on —
  // `transport` was NOT touched by this slice.
  const offline = hooks.fleetLoadErrorHtml({ status: 0, data: { error: "network_error" }, text: null, transport: "offline" });
  assert.match(offline, /offline/i);
  // Total over an absent fault (the seam passes fleetFault, which can be null).
  assert.match(hooks.fleetLoadErrorHtml(null), /Couldn't load this instance/);
});

// ── cch-w34-s1 · A FAILED READ IS NOT AN EMPTY ONE ─────────────────────────
// The wave-34 law (charter D382), driven rather than read. Both loaders folded
// `r.ok` into a value-coalescing default — `(r.ok && r.data && r.data.X) || []`
// — so a 500 and a 403 produced the SAME value as a genuine 200-with-nothing,
// and the person read a determinate assertion the console never received:
// "No sites yet" on the instance workspace, "No API tokens yet" beside a
// Create-token button on the tokens page.
//
// Why these are DRIVEN and not asserted from markup: the collapse lives inside
// the fetch callback, which is exactly why nothing in this harness could see it
// (loadInstanceSites was mentioned five times, every one of them an assertion
// that its slot exists in the static HTML). fakeDom() is unusable here — its
// innerHTML setter regex-extracts class names and THROWS THE MARKUP AWAY, so it
// cannot assert copy. These use a recording-innerHTML stub, on the
// driveBootOAuth precedent above (swap the sandbox globals, drive, restore).

// A DOM whose innerHTML assignments are KEPT verbatim, keyed by element id. The
// whole point is the bytes: a census can prove the fold is gone, only rendered
// copy can prove what the person actually reads.
function recordingDom(ids) {
  const els = {};
  for (const id of ids) {
    els[id] = {
      id,
      _html: "",
      writes: [],
      get innerHTML() { return this._html; },
      set innerHTML(v) { this._html = String(v); this.writes.push(String(v)); },
      onclick: null,
      addEventListener() {},
      querySelectorAll() { return []; },
      querySelector() { return null; },
      getAttribute() { return null; },
    };
  }
  return {
    els,
    document: {
      querySelector(sel) { return els[String(sel).replace(/^#/, "")] || null; },
      getElementById(id) { return els[id] || null; },
      querySelectorAll() { return []; },
      createElement: () => ({ ...inertEl }),
    },
  };
}

// Swap fetch + document, run one loader to completion, restore. api() resolves
// on a microtask chain, so draining the queue settles the paint.
async function driveLoader(run, { status, payload, ids }) {
  const saved = { fetch: sandbox.fetch, document: sandbox.document };
  const dom = recordingDom(ids);
  const fetch = fetchStub(status, payload);
  sandbox.fetch = fetch;
  sandbox.document = dom.document;
  try {
    run();
    for (let i = 0; i < 12; i++) await Promise.resolve();
  } finally {
    Object.assign(sandbox, saved);
  }
  return { dom, fetch, html: () => dom.els[ids[0]].innerHTML };
}

// ── connect agent: the fetch->reveal wiring, driven (cloud-agent onramp) ─────
//
// The pins further up prove the reveal COMPOSES correctly. They cannot prove it
// is REACHED, and reachability is where a credential surface actually fails: a
// read that 403s must open no sheet at all, because a modal titled "Connect
// agent" over an empty token line is a worse answer than a toast.
//
// `token-copy` and `token-done` are in the id list because revealToken binds
// their click handlers UNGUARDED (main's shape, not this slice's) — the
// recordingDom must be able to hand them back or the drive throws before it can
// assert anything.
const CONNECT_IDS = ["modal-root", "modal-body", "token-copy", "token-done"];
const CONNECT_BP = { id: "bp-1", name: "Acme prod", host: "acme.example", url: "https://acme.barkpark.cloud" };

const driveConnect = (status, payload) =>
  driveLoader(() => hooks.connectAgent(CONNECT_BP, null), { status, payload, ids: CONNECT_IDS });

test("connect agent: a 200 opens the reveal, and it asks the credentials route for THIS box", async () => {
  const { dom, fetch } = await driveConnect(200, {
    admin_token: "bp_admin_DRIVEN",
    url: "https://acme.barkpark.cloud",
    host: "acme.example",
  });

  assert.equal(fetch.calls.length, 1);
  assert.match(fetch.calls[0].path, /\/v1\/barkparks\/bp-1\/credentials$/);

  const body = dom.els["modal-body"].innerHTML;
  assert.match(body, /Connect agent/);
  assert.match(body, /bp_admin_DRIVEN/);
  assert.match(body, /https:\/\/acme\.barkpark\.cloud/);
  // Reached through the mint's component, not a second implementation.
  assert.match(body, /token-reveal-input/);
  assert.ok(!body.toLowerCase().includes("only time"));
});

test("connect agent: a REFUSED read opens NO sheet — an empty reveal is worse than a toast", async () => {
  for (const [status, payload] of [
    [403, { error: "forbidden", required: "root", scope: "token" }],
    [404, { error: "no_admin_token" }],
    [409, { error: "suspended" }],
    [500, { error: "server_error" }],
  ]) {
    const { dom } = await driveConnect(status, payload);
    assert.equal(dom.els["modal-body"].writes.length, 0,
      "status " + status + " must not paint a reveal sheet");
  }
});

test("connect agent: a 200 carrying NO token is treated as a failure, not as an empty reveal", async () => {
  // The route can answer 200 only with a token, but the client must not assume
  // it: `r.data.admin_token` absent would otherwise render the amber sheet with
  // an empty <code> — a credential screen asserting a credential it does not have.
  const { dom } = await driveConnect(200, { url: "https://acme.barkpark.cloud" });
  assert.equal(dom.els["modal-body"].writes.length, 0);
});

